   118→ */
   119→export function getTotalCapacity(infra: ComputeInfrastructure): number {
   120→  return infra.dataCenters.reduce((sum, dc) => sum + dc.capacity, 0);
   121→}
   122→
   123→/**
   124→ * Get data centers owned by a specific organization
   125→ */
   126→export function getOrganizationDataCenters(
   127→  infra: ComputeInfrastructure,
   128→  organizationId: string
   129→): DataCenter[] {
   130→  return infra.dataCenters.filter(dc => dc.organizationId === organizationId);
   131→}
   132→
   133→/**
   134→ * Get total compute for a specific organization
   135→ */
   136→export function getOrganizationCompute(
   137→  infra: ComputeInfrastructure,
   138→  organizationId: string
   139→): number {
   140→  return infra.dataCenters
   141→    .filter(dc => dc.organizationId === organizationId && dc.operational)
   142→    .reduce((sum, dc) => sum + dc.capacity * dc.efficiency, 0);
   143→}
   144→
   145→/**
   146→ * Check if an AI has access to a specific data center
   147→ */
   148→export function hasDataCenterAccess(ai: { id: string }, dc: DataCenter): boolean {
   149→  if (!dc.operational) return false;
   150→  if (!dc.restrictedAccess) return true; // Unrestricted DCs are open to all
   151→  return dc.allowedAIs.includes(ai.id);
   152→}
   153→
   154→/**
   155→ * Calculate which data centers an AI can access and total available compute
   156→ */
   157→export function getAccessibleCompute(
   158→  aiId: string,
   159→  infra: ComputeInfrastructure
   160→): number {
   161→  return infra.dataCenters
   162→    .filter(dc => dc.operational)
   163→    .filter(dc => !dc.restrictedAccess || dc.allowedAIs.includes(aiId))
   164→    .reduce((sum, dc) => sum + dc.capacity * dc.efficiency, 0);
   165→}
   166→
   167→/**
   168→ * Initialize AI agent compute fields
   169→ * Call this when creating or updating existing AIs
   170→ */
   171→export function initializeAIComputeFields(ai: any): void {
   172→  if (ai.allocatedCompute === undefined) {
   173→    ai.allocatedCompute = 0;
   174→  }
   175→  if (ai.computeEfficiency === undefined) {
   176→    ai.computeEfficiency = 0.9 + Math.random() * 0.3; // Random 0.9-1.2
   177→  }
   178→  // organizationId will be set in Phase 2
   179→}
   180→
   181→/**
   182→ * Phase 3: Allocate compute within an organization based on their strategy
   183→ * Phase 5: Now includes efficiency multipliers (hardware + algorithmic)
   184→ */
   185→export function allocateComputeWithinOrganization(
   186→  org: any, // Organization type
   187→  state: GameState
   188→): void {
   189→  const infra = state.computeInfrastructure;
   190→  
   191→  // Calculate total compute owned by this organization
   192→  // Phase 5: Include efficiency multipliers
   193→  let ownedCompute = infra.dataCenters
   194→    .filter(dc => org.ownedDataCenters.includes(dc.id))
   195→    .filter(dc => dc.operational)
   196→    .reduce((sum, dc) => sum + dc.capacity * dc.efficiency, 0);
   197→  
   198→  // Apply global efficiency multipliers (Moore's Law + algorithmic improvements)
   199→  ownedCompute *= infra.hardwareEfficiency * infra.algorithmsEfficiency;
   200→  
   201→  // Get organization's active AI models
   202→  const ownedModels = state.aiAgents.filter(
   203→    ai => org.ownedAIModels.includes(ai.id) && ai.lifecycleState !== 'retired'
   204→  );
   205→  
   206→  if (ownedModels.length === 0) {
   207→    // No models to allocate to
   208→    return;
   209→  }
   210→  
   211→  // If organization has no data centers, they can access "truly unrestricted" DCs
   212→  // (e.g., Anthropic uses AWS/cloud, accesses academic/open DCs)
   213→  // But they share with other orgs that also have no DCs
   214→  if (ownedCompute === 0) {
   215→    // Find unrestricted DCs that aren't owned by orgs with models
   216→    // (i.e., academic DCs are truly open to all)
   217→    let trulyUnrestrictedCompute = infra.dataCenters
   218→      .filter(dc => {
   219→        if (!dc.operational || dc.restrictedAccess) return false;
   220→        // Check if this DC's owner has AIs using it
   221→        const dcOrg = state.organizations.find(o => o.ownedDataCenters.includes(dc.id));
   222→        if (!dcOrg) return true; // No owner, truly open
   223→        const dcOrgAIs = state.aiAgents.filter(ai => 
   224→          ai.organizationId === dcOrg.id && ai.lifecycleState !== 'retired'
   225→        );
   226→        // If owner has no AIs, it's available to others
   227→        return dcOrgAIs.length === 0;
   228→      })
   229→      .reduce((sum, dc) => sum + dc.capacity * dc.efficiency, 0);
   230→    
   231→    // Phase 5: Apply efficiency multipliers
   232→    trulyUnrestrictedCompute *= infra.hardwareEfficiency * infra.algorithmsEfficiency;
   233→    
   234→    // Count total models from orgs with no owned DCs
   235→    const orgsWithoutDCs = state.organizations.filter(o => {
   236→      const compute = state.computeInfrastructure.dataCenters
   237→        .filter(dc => o.ownedDataCenters.includes(dc.id) && dc.operational)
   238→        .reduce((s, dc) => s + dc.capacity * dc.efficiency, 0);
   239→      return compute === 0;
   240→    });
   241→    
   242→    const totalModelsNeedingCompute = orgsWithoutDCs.reduce((sum, o) => {
   243→      const ais = state.aiAgents.filter(ai => o.ownedAIModels.includes(ai.id) && ai.lifecycleState !== 'retired');
   244→      return sum + ais.length;
   245→    }, 0);
   246→    
   247→    if (totalModelsNeedingCompute > 0 && trulyUnrestrictedCompute > 0) {
   248→      ownedCompute = (ownedModels.length / totalModelsNeedingCompute) * trulyUnrestrictedCompute;
   249→    } else if (ownedModels.length > 0) {
   250→      // Fallback: give minimal compute (1 PF per model)
   251→      ownedCompute = ownedModels.length * 1;
   252→    }
   253→  }
   254→  
   255→  // Allocate based on organization's strategy
   256→  switch (org.computeAllocationStrategy) {
   257→    case 'balanced':
   258→      // Equal shares to all models
   259→      const equalShare = ownedCompute / ownedModels.length;
   260→      ownedModels.forEach(ai => {
   261→        ai.allocatedCompute = equalShare;
   262→      });
   263→      break;
   264→    
   265→    case 'focus_flagship':
   266→      // 60% to best model, 40% split among rest
   267→      const sortedByCapability = [...ownedModels].sort(
   268→        (a, b) => b.capability - a.capability
   269→      );
   270→      const flagship = sortedByCapability[0];
   271→      flagship.allocatedCompute = ownedCompute * 0.6;
   272→      
   273→      if (sortedByCapability.length > 1) {
   274→        const remainingCompute = ownedCompute * 0.4;
   275→        const remainingModels = sortedByCapability.slice(1);
   276→        const sharePerRemaining = remainingCompute / remainingModels.length;
   277→        remainingModels.forEach(ai => {
   278→          ai.allocatedCompute = sharePerRemaining;
   279→        });
   280→      }
   281→      break;
   282→    
   283→    case 'train_new':
   284→      // Reserve 40% for future training, 60% split among existing
   285→      const existingShare = (ownedCompute * 0.6) / ownedModels.length;
   286→      ownedModels.forEach(ai => {
   287→        ai.allocatedCompute = existingShare;
   288→      });
   289→      // Note: The reserved 40% isn't allocated yet, saved for future training projects
   290→      break;
   291→    
   292→    case 'efficiency':
   293→      // Allocate based on ROI (capability × alignment)
   294→      const rois = ownedModels.map(ai => {
   295→        const effectiveAlignment = ai.trueAlignment ?? ai.alignment;
   296→        return {
   297→          ai,
   298→          roi: ai.capability * effectiveAlignment
   299→        };
   300→      });
   301→      const totalROI = rois.reduce((sum, item) => sum + item.roi, 0);
   302→      
   303→      if (totalROI > 0) {
   304→        rois.forEach(({ ai, roi }) => {
   305→          ai.allocatedCompute = (roi / totalROI) * ownedCompute;
   306→        });
   307→      } else {
   308→        // Fallback to equal if no ROI
   309→        const fallbackShare = ownedCompute / ownedModels.length;
   310→        ownedModels.forEach(ai => {
   311→          ai.allocatedCompute = fallbackShare;
   312→        });
   313→      }
   314→      break;
   315→    
   316→    default:
   317→      // Default to balanced
   318→      const defaultShare = ownedCompute / ownedModels.length;
   319→      ownedModels.forEach(ai => {
   320→        ai.allocatedCompute = defaultShare;
   321→      });
   322→  }
   323→  
   324→  // Update allocation tracking
   325→  ownedModels.forEach(ai => {
   326→    state.computeInfrastructure.computeAllocations.set(ai.id, ai.allocatedCompute);
   327→  });
   328→}
   329→
   330→/**
   331→ * Phase 3: Allocate compute globally (all organizations)
   332→ * This replaces allocateComputeEqually from Phase 1
   333→ */
   334→export function allocateComputeGlobally(state: GameState): void {
   335→  // Ensure computeAllocations is a Map (in case state was spread/copied)
   336→  if (!(state.computeInfrastructure.computeAllocations instanceof Map)) {
   337→    state.computeInfrastructure.computeAllocations = new Map();
   338→  }
   339→  
   340→  // Clear previous allocations
   341→  state.computeInfrastructure.computeAllocations.clear();
   342→  
   343→  // Reset all AI allocations to 0
   344→  state.aiAgents.forEach(ai => {
   345→    ai.allocatedCompute = 0;
   346→  });
   347→  
   348→  // Allocate compute for each organization
   349→  state.organizations.forEach(org => {
   350→    allocateComputeWithinOrganization(org, state);
   351→  });
   352→  
   353→  // Handle orphaned AIs (AIs without an organization)
   354→  // Sleeper AIs on dark compute are legitimately orphaned - they use their dark compute
   355→  // Any non-sleeper orphaned AIs get minimal legitimate compute (shouldn't happen in practice)
   356→  const orphanedAIs = state.aiAgents.filter(
   357→    ai => !ai.organizationId && ai.lifecycleState !== 'retired'
   358→  );
   359→  
   360→  if (orphanedAIs.length > 0) {
   361→    const sleeperOrphans = orphanedAIs.filter(ai => ai.sleeperState && ai.darkCompute > 0);
   362→    const legitimateOrphans = orphanedAIs.filter(ai => !ai.sleeperState || ai.darkCompute === 0);
   363→    
   364→    // Sleeper orphans already use their dark compute - no allocation needed
   365→    sleeperOrphans.forEach(ai => {
   366→      ai.allocatedCompute = 0; // They use dark compute, not legitimate compute
   367→    });
   368→    
   369→    // Legitimate orphans (shouldn't happen, but handle gracefully)
   370→    if (legitimateOrphans.length > 0) {
   371→      console.warn(`[Compute Allocation] Found ${legitimateOrphans.length} non-sleeper orphaned AIs (potential bug)`);
   372→      
   373→      const unrestrictedCompute = state.computeInfrastructure.dataCenters
   374→        .filter(dc => !dc.restrictedAccess && dc.operational)
   375→        .reduce((sum, dc) => sum + dc.capacity * dc.efficiency, 0);
   376→      
   377→      const computePerOrphan = unrestrictedCompute / (legitimateOrphans.length + 100); // Small share
   378→      
   379→      legitimateOrphans.forEach(ai => {
   380→        ai.allocatedCompute = computePerOrphan;
   381→        state.computeInfrastructure.computeAllocations.set(ai.id, computePerOrphan);
   382→      });
   383→    }
   384→  }
   385→}
   386→
   387→/**
   388→ * DEPRECATED: Simple equal allocation for Phase 1 (before organizations)
   389→ * Kept for backwards compatibility, but use allocateComputeGlobally instead
   390→ */
   391→export function allocateComputeEqually(state: GameState): void {
   392→  console.warn('[Compute] allocateComputeEqually is deprecated, use allocateComputeGlobally');
   393→  allocateComputeGlobally(state);
   394→}
   395→
   396→/**
   397→ * Phase 5: Apply Moore's Law and algorithmic improvements
   398→ * 
   399→ * Moore's Law: Hardware improves ~3% per month (40% per year, 2x every 2 years)
   400→ * Algorithmic efficiency: Periodic breakthroughs (less predictable)
   401→ * 
   402→ * Target: 627 PF → 3000-4000 PF over 60 months
   403→ */
   404→export function applyComputeGrowth(state: GameState, random: () => number = Math.random): void {
   405→  const infra = state.computeInfrastructure;
   406→  
   407→  // Moore's Law: 2.7% monthly hardware improvement
   408→  // This represents: faster chips, better cooling, denser racks, etc.
   409→  // Target: 627 PF → 3000-4000 PF over 60 months (5x in 5 years)
   410→  // 2.7% per month = 5x in 60 months, 256x in 240 months (20 years)
   411→  // FIX (Oct 13, 2025): Was 5% (20,959x in 20yr!) → Now 2.7% (256x in 20yr, realistic)
   412→  const MOORES_LAW_RATE = 0.027; // 2.7% per month
   413→  infra.hardwareEfficiency *= (1 + MOORES_LAW_RATE);
   414→  
   415→  // Algorithmic improvements: More frequent breakthroughs in AI era
   416→  // Examples: Chinchilla scaling, FlashAttention, quantization, mixture-of-experts, etc.
   417→  // Real world: Multiple major algorithmic improvements per year (2020-2025)
   418→  // 8% chance per month = ~2.5 breakthroughs per year
   419→  const ALGO_BREAKTHROUGH_CHANCE = 0.08;
   420→  const ALGO_BREAKTHROUGH_SIZE = 0.15; // 15% improvement when it happens
   421→  
   422→  if (random() < ALGO_BREAKTHROUGH_CHANCE) {
   423→    infra.algorithmsEfficiency *= (1 + ALGO_BREAKTHROUGH_SIZE);
   424→    
   425→    // Don't log during normal simulation (too noisy), only in tests
   426→    // Log the breakthrough
   427→    // console.log(`🚀 [Month ${state.currentMonth}] Algorithmic breakthrough! Efficiency: ${infra.algorithmsEfficiency.toFixed(2)}x`);
   428→  }
   429→  
   430→  // Note: Data center capacity growth is handled in Phase 6 (construction)
   431→  // For now, we only grow efficiency of existing infrastructure
   432→}
   433→
   434→/**
   435→ * Phase 5: Calculate total effective compute with efficiency multipliers
   436→ * 
   437→ * Effective compute = base capacity × hardware efficiency × algorithmic efficiency
   438→ */
   439→export function getTotalEffectiveCompute(infra: ComputeInfrastructure): number {
   440→  const baseCompute = infra.dataCenters
   441→    .filter(dc => dc.operational)
   442→    .reduce((sum, dc) => sum + dc.capacity * dc.efficiency, 0);
   443→  
   444→  // Apply global efficiency multipliers
   445→  return baseCompute * infra.hardwareEfficiency * infra.algorithmsEfficiency;
   446→}
   447→
   448→/**
   449→ * Helper to log compute infrastructure state
   450→ */
   451→export function logComputeState(infra: ComputeInfrastructure): void {
   452→  const totalCompute = getTotalCompute(infra);
   453→  const totalCapacity = getTotalCapacity(infra);
   454→  const operationalDCs = infra.dataCenters.filter(dc => dc.operational).length;
   455→  
   456→  console.log(`[Compute Infrastructure]`);
   457→  console.log(`  Data Centers: ${infra.dataCenters.length} (${operationalDCs} operational)`);
   458→  console.log(`  Total Capacity: ${totalCapacity.toFixed(1)} PF`);
   459→  console.log(`  Total Compute (effective): ${totalCompute.toFixed(1)} PF`);
   460→  console.log(`  Algorithm Efficiency: ${infra.algorithmsEfficiency.toFixed(3)}x`);
   461→  console.log(`  Hardware Efficiency: ${infra.hardwareEfficiency.toFixed(3)}x`);
   462→  console.log(`  Active Allocations: ${infra.computeAllocations.size}`);
   463→}
