   715→    const { determinePopulationOutcome, logDeathSummary } = require('./populationDynamics');
   716→    const { logRegionalPopulationSummary } = require('./regionalPopulations');
   717→
   718→    const finalPopOutcome = determinePopulationOutcome(state);
   719→    console.log(`\n👥 FINAL POPULATION STATUS:`);
   720→    console.log(`   Status: ${finalPopOutcome.status.toUpperCase()}`);
   721→    console.log(`   Final Population: ${finalPopOutcome.finalPopulation.toFixed(2)}B`);
   722→    console.log(`   Peak Population: ${finalPopOutcome.peakPopulation.toFixed(2)}B`);
   723→    console.log(`   Decline: ${finalPopOutcome.populationDecline.toFixed(1)}%`);
   724→    console.log(`   ${finalPopOutcome.outcomeNarrative}\n`);
   725→
   726→    // Log death summary statistics (TIER 1.5)
   727→    logDeathSummary(state);
   728→
   729→    // Log regional population breakdown (TIER 1.5 - Phase 5)
   730→    logRegionalPopulationSummary(state);
   731→
   732→    // Finalize log
   733→    const log = logger.finalize(state, finalOutcome);
   734→    const diagnostics = diagnosticLogger.finalize(state, finalOutcome);
   735→
   736→    // Print diagnostic report if verbose
   737→    if (process.env.VERBOSE_DIAGNOSTICS === 'true') {
   738→      console.log(formatDiagnosticReport(diagnostics));
   739→    }
   740→    
   741→    return {
   742→      finalState: state,
