   747→        totalMonths: history.length,
   748→        finalOutcome,
   749→        finalOutcomeReason: actualOutcomeReason || `Reached max months (${maxMonths}) with ${finalOutcome} probability dominant`,
   750→        finalOutcomeProbability,
   751→        criticalEvents: log.events.criticalEvents,
   752→        economicStageReached: state.globalMetrics.economicTransitionStage
   753→      }
   754→    };
   755→  }
