   119→/**
   120→ * Run Monte Carlo simulation
   121→ */
   122→export async function runMonteCarlo(
   123→  initialState: GameState,
   124→  config: MonteCarloConfig
   125→): Promise<MonteCarloResults> {
   126→  console.log(`Starting Monte Carlo simulation with ${config.numRuns} runs...`);
   127→  
   128→  const runs: SimulationRunResult[] = [];
   129→  
   130→  // Generate parameter combinations
   131→  const parameterCombinations = generateParameterCombinations(config);
   132→  
   133→  // Run simulations
   134→  for (let i = 0; i < config.numRuns; i++) {
   135→    if (i % 100 === 0) {
   136→      console.log(`Progress: ${i}/${config.numRuns} (${((i / config.numRuns) * 100).toFixed(1)}%)`);
   137→    }
   138→    
   139→    // Select parameter combination
   140→    const params = parameterCombinations[i % parameterCombinations.length];
   141→    
   142→    // Create varied initial state
   143→    const variedState = varyInitialState(initialState, config.initialStateVariation);
   144→    
   145→    // Run simulation
   146→    const engineConfig: SimulationConfig = {
   147→      seed: i, // Use run index as seed for reproducibility
   148→      ...params
   149→    };
   150→    if (config.maxMonths !== undefined) {
   151→      engineConfig.maxMonths = config.maxMonths;
   152→    }
   153→    const engine = new SimulationEngine(engineConfig);
   154→
   155→    const runConfig: { maxMonths?: number; checkActualOutcomes?: boolean } = {};
   156→    if (config.maxMonths !== undefined) {
   157→      runConfig.maxMonths = config.maxMonths;
   158→    }
   159→    const result = engine.run(variedState, runConfig);
   160→    
   161→    runs.push(result);
   162→  }
   163→  
   164→  console.log('Simulation complete. Analyzing results...');
   165→  
   166→  // Analyze results
   167→  return analyzeMonteCarloResults(runs, config);
   168→}
   169→
   170→/**
   171→ * Generate all parameter combinations to test
   172→ */
   173→function generateParameterCombinations(config: MonteCarloConfig): SimulationConfig[] {
   174→  const combinations: SimulationConfig[] = [];
   175→  
   176→  if (!config.parameters) {
   177→    // No parameter sweep - use defaults
   178→    return [{}];
   179→  }
   180→  
   181→  const {
   182→    governmentActionFrequency = [0.08],
   183→    socialAdaptationRate = [1.0]
   184→  } = config.parameters;
   185→  
   186→  // Generate Cartesian product of all parameter values
   187→  for (const govFreq of governmentActionFrequency) {
   188→    for (const adaptRate of socialAdaptationRate) {
   189→      combinations.push({
   190→        governmentActionFrequency: govFreq,
   191→        socialAdaptationRate: adaptRate
   192→      });
   193→    }
   194→  }
   195→  
   196→  return combinations.length > 0 ? combinations : [{}];
   197→}
   198→
   199→/**
   200→ * Add variation to initial state based on configuration
   201→ */
   202→function varyInitialState(
   203→  baseState: GameState,
   204→  variation?: MonteCarloConfig['initialStateVariation']
   205→): GameState {
   206→  if (!variation) return baseState;
   207→  
   208→  const variedState = JSON.parse(JSON.stringify(baseState)); // Deep clone
   209→  
   210→  // Vary AI agent properties
   211→  if (variation.aiCapability || variation.aiAlignment) {
   212→    variedState.aiAgents = variedState.aiAgents.map((ai: unknown) => {
   213→      const agent = ai as { capability: number; alignment: number };
   214→      return {
   215→        ...agent,
   216→        capability: variation.aiCapability 
   217→          ? gaussianRandom(variation.aiCapability.mean, variation.aiCapability.stdDev)
   218→          : agent.capability,
   219→        alignment: variation.aiAlignment
   220→          ? Math.max(0, Math.min(1, gaussianRandom(variation.aiAlignment.mean, variation.aiAlignment.stdDev)))
   221→          : agent.alignment
   222→      };
   223→    });
   224→  }
   225→  
   226→  // Vary society properties
   227→  if (variation.unemployment) {
   228→    variedState.society.unemploymentLevel = Math.max(0, Math.min(1,
   229→      gaussianRandom(variation.unemployment.mean, variation.unemployment.stdDev)
   230→    ));
   231→  }
   232→  
   233→  if (variation.trustInAI) {
   234→    variedState.society.trustInAI = Math.max(0, Math.min(1,
   235→      gaussianRandom(variation.trustInAI.mean, variation.trustInAI.stdDev)
   236→    ));
   237→  }
   238→  
   239→  return variedState;
   240→}
   241→
   242→/**
   243→ * Box-Muller transform for Gaussian random numbers
   244→ */
   245→function gaussianRandom(mean: number, stdDev: number): number {
   246→  const u1 = Math.random();
   247→  const u2 = Math.random();
   248→  const z0 = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
   249→  return mean + z0 * stdDev;
   250→}
   251→
   252→/**
   253→ * Analyze dystopia statistics across all runs
   254→ */
   255→function analyzeDystopiaStatistics(runs: SimulationRunResult[]): DystopiaAnalysis {
   256→  const variantFrequency: Record<string, number> = {};
   257→  const severityDistribution: Record<string, number> = {};
   258→  const entryReasons: Record<string, number> = {};
   259→  const durations: number[] = [];
   260→
   261→  let totalRunsWithDystopia = 0;
   262→  let escaped = 0;
   263→  let stayedIn = 0;
   264→  let wentExtinct = 0;
   265→
   266→  runs.forEach(run => {
   267→    const finalOutcome = run.summary.finalOutcome;
   268→    const finalProb = run.finalState.outcomeMetrics.dystopiaProbability;
   269→
   270→    // Consider a run as having experienced dystopia if:
   271→    // 1. Final outcome is dystopia, OR
   272→    // 2. Dystopia probability reached significant levels (>0.7) at any point
   273→    const snapshots = run.log.snapshots.quartiles || [];
   274→    const maxDystopiaProb = snapshots.length > 0
   275→      ? Math.max(...snapshots.map((s: { dystopiaProbability: number }) => s.dystopiaProbability))
   276→      : finalProb;
   277→
   278→    const experiencedDystopia = finalOutcome === 'dystopia' || maxDystopiaProb >= 0.7;
   279→
   280→    if (experiencedDystopia) {
   281→      totalRunsWithDystopia++;
   282→
   283→      // Track severity based on final dystopia probability
   284→      if (finalOutcome === 'dystopia') {
   285→        if (finalProb >= 0.95) {
   286→          severityDistribution['severe'] = (severityDistribution['severe'] || 0) + 1;
   287→        } else if (finalProb >= 0.85) {
   288→          severityDistribution['moderate'] = (severityDistribution['moderate'] || 0) + 1;
   289→        } else {
   290→          severityDistribution['mild'] = (severityDistribution['mild'] || 0) + 1;
   291→        }
   292→      }
   293→
   294→      // Track outcome correlation
   295→      if (finalOutcome === 'utopia' || finalOutcome === 'inconclusive') {
   296→        escaped++;
   297→      } else if (finalOutcome === 'dystopia') {
   298→        stayedIn++;
   299→      } else if (finalOutcome === 'extinction') {
   300→        wentExtinct++;
   301→      }
   302→
   303→      // Estimate duration by finding when dystopia prob crossed threshold
   304→      const dystopiaThreshold = 0.7;
   305→      let entryMonth = -1;
   306→      let exitMonth = -1;
   307→
   308→      for (let i = 0; i < snapshots.length; i++) {
   309→        const snapshot = snapshots[i];
   310→        if (!snapshot) continue;
   311→        if (entryMonth === -1 && snapshot.dystopiaProbability >= dystopiaThreshold) {
   312→          entryMonth = snapshot.month;
   313→        }
   314→        if (entryMonth !== -1 && snapshot.dystopiaProbability < dystopiaThreshold) {
   315→          exitMonth = snapshot.month;
   316→          break;
   317→        }
   318→      }
   319→
   320→      if (entryMonth !== -1) {
   321→        if (exitMonth !== -1) {
   322→          durations.push(exitMonth - entryMonth);
   323→        } else if (finalOutcome === 'dystopia') {
   324→          // Still in dystopia at end
   325→          durations.push(run.summary.totalMonths - entryMonth);
   326→        }
   327→      }
   328→
   329→      // Analyze potential entry reasons from critical events around dystopia spike
   330→      run.log.events.criticalEvents.forEach(event => {
   331→        if (event.severity === 'destructive' || event.type === 'crisis') {
   332→          const reason = event.title;
   333→          entryReasons[reason] = (entryReasons[reason] || 0) + 1;
   334→        }
   335→      });
   336→    }
   337→  });
   338→
   339→  // Compute duration statistics
   340→  let durationStats = {
   341→    average: 0,
   342→    median: 0,
   343→    min: 0,
   344→    max: 0
   345→  };
   346→
   347→  if (durations.length > 0) {
   348→    const sortedDurations = durations.sort((a, b) => a - b);
   349→    durationStats = {
   350→      average: durations.reduce((a, b) => a + b, 0) / durations.length,
   351→      median: sortedDurations[Math.floor(sortedDurations.length / 2)] || 0,
   352→      min: sortedDurations[0] || 0,
   353→      max: sortedDurations[sortedDurations.length - 1] || 0
   354→    };
   355→  }
   356→
   357→  return {
   358→    totalRunsWithDystopia,
   359→    variantFrequency,
   360→    severityDistribution,
   361→    entryReasons,
   362→    durationStats,
   363→    outcomeCorrelation: {
   364→      escaped,
   365→      stayedIn,
   366→      wentExtinct
   367→    }
   368→  };
   369→}
   370→
   371→/**
   372→ * Analyze Monte Carlo results and compute statistics
   373→ */
   374→function analyzeMonteCarloResults(
   375→  runs: SimulationRunResult[],
   376→  config: MonteCarloConfig
   377→): MonteCarloResults {
   378→  // Count outcomes
   379→  const outcomeCounts = {
   380→    utopia: 0,
   381→    dystopia: 0,
   382→    extinction: 0,
   383→    inconclusive: 0
   384→  };
   385→  
   386→  let totalQoL = 0;
   387→  let totalUnemployment = 0;
   388→  let totalEconomicStage = 0;
   389→  let totalTrust = 0;
   390→  let totalMonths = 0;
   391→  
   392→  // Build probability distributions for each run
   393→  const probabilityByRun = runs.map((run, runId) => {
   394→    // Get final outcome metrics (probabilities)
   395→    const finalMetrics = run.finalState.outcomeMetrics;
   396→    const extinctionState = run.finalState.extinctionState;
   397→    
   398→    return {
   399→      runId,
   400→      months: run.summary.totalMonths,
   401→      outcome: run.summary.finalOutcome,
   402→      probabilities: {
   403→        utopia: finalMetrics.utopiaProbability,
   404→        dystopia: finalMetrics.dystopiaProbability,
   405→        extinction: finalMetrics.extinctionProbability
   406→      },
   407→      extinctionType: extinctionState.active ? extinctionState.type : null,
   408→      extinctionMechanism: extinctionState.active ? extinctionState.mechanism : null
   409→    };
   410→  });
   411→  
   412→  // Sort by utopia probability (high to low)
   413→  const sortedByUtopia = [...probabilityByRun]
   414→    .sort((a, b) => b.probabilities.utopia - a.probabilities.utopia)
   415→    .map(r => r.runId);
   416→  
   417→  // Sort by extinction probability (low to high - best worlds first)
   418→  const sortedByExtinction = [...probabilityByRun]
   419→    .sort((a, b) => a.probabilities.extinction - b.probabilities.extinction)
   420→    .map(r => r.runId);
   421→  
   422→  runs.forEach(run => {
   423→    outcomeCounts[run.summary.finalOutcome]++;
   424→    totalQoL += run.finalState.globalMetrics.qualityOfLife;
   425→    totalUnemployment += run.finalState.society.unemploymentLevel;
   426→    totalEconomicStage += run.finalState.globalMetrics.economicTransitionStage;
   427→    totalTrust += run.finalState.society.trustInAI;
   428→    totalMonths += run.summary.totalMonths;
   429→  });
   430→  
   431→  const numRuns = runs.length;
   432→
   433→  // Analyze dystopia statistics
   434→  const dystopiaAnalysis = analyzeDystopiaStatistics(runs);
   435→
   436→  return {
   437→    runs,
   438→    config,
   439→    outcomeDistribution: {
   440→      utopia: outcomeCounts.utopia / numRuns,
   441→      dystopia: outcomeCounts.dystopia / numRuns,
   442→      extinction: outcomeCounts.extinction / numRuns,
   443→      inconclusive: outcomeCounts.inconclusive / numRuns
   444→    },
   445→    probabilityDistributions: {
   446→      byRun: probabilityByRun,
   447→      sortedByUtopia,
   448→      sortedByExtinction
   449→    },
   450→    averageMetrics: {
   451→      finalQualityOfLife: totalQoL / numRuns,
   452→      finalUnemployment: totalUnemployment / numRuns,
   453→      finalEconomicStage: totalEconomicStage / numRuns,
   454→      finalTrust: totalTrust / numRuns,
   455→      monthsToOutcome: totalMonths / numRuns
   456→    },
   457→    dystopiaAnalysis: dystopiaAnalysis.totalRunsWithDystopia > 0 ? dystopiaAnalysis : undefined
   458→  };
   459→}
