  console.log(`Run ${run.seed} deaths:`, deaths); // Debug output

  totalDeaths.natural += deaths.natural || 0;
  totalDeaths.crisis += (deaths.famine || 0) + (deaths.disease || 0) + ...
  // Make sure ALL categories are included
});
```

