/**
 * P0.4 Diagnostic Logging - Identify Sources of Determinism
 *
 * Purpose: Track metrics across Monte Carlo runs to identify which systems
 * produce IDENTICAL values (indicating deterministic behavior).
 *
 * Usage: Run Monte Carlo with diagnostics enabled, compare outputs across runs.
 * Metrics that are identical to 6+ decimal places reveal deterministic formulas.
 */

import { GameState } from '@/types/game';
import * as fs from 'fs';
import * as path from 'path';

export interface DiagnosticSnapshot {
  month: number;
  seed: number;

  // Population metrics
  population: number;
  monthlyDeaths: number;
  mortalityRate: number;
  birthRate: number;

  // Resource metrics
  waterReserves?: number;
  foodProduction?: number;
  resourceReserves?: number;

  // Environmental metrics
  climateStability: number;
  biodiversityIndex: number;
  pollutionLevel: number;
  tippingPointRisk: number;
  cascadeActive: boolean;
  cascadeSeverity: number;

  // Economic metrics
  gdpMultiplier?: number;
  unemploymentLevel?: number;
  bankrupt Organization sCount: number;
  totalCapital: number;

  // Crisis metrics
  activeCrises: number;
  famineSeverity?: number;

  // QoL metrics
  qualityOfLife: number;
  foodSecurity: number;
  waterSecurity?: number;
}

let diagnosticLog: DiagnosticSnapshot[] = [];
let currentSeed: number = 0;
let outputPath: string | null = null;

/**
 * Initialize diagnostics for a Monte Carlo run
 */
export function initializeDiagnostics(seed: number, outputDir?: string): void {
  currentSeed = seed;
  diagnosticLog = [];

  if (outputDir) {
    outputPath = path.join(outputDir, `diagnostics_seed_${seed}.json`);
  }
}

/**
 * Capture diagnostic snapshot of current game state
 * Call this every N months (e.g., every 6 or 12 months)
 */
export function captureDiagnosticSnapshot(state: GameState, month: number): void {
  const snapshot: DiagnosticSnapshot = {
    month,
    seed: currentSeed,

    // Population
    population: state.humanPopulationSystem.population,
    monthlyDeaths: state.humanPopulationSystem.deathsThisMonth || 0,
    mortalityRate: calculateMortalityRate(state),
    birthRate: state.humanPopulationSystem.adjustedBirthRate || 0,

    // Resources
    waterReserves: (state as any).freshwaterSystem?.groundwaterPercent,
    foodProduction: state.resourceEconomy?.food?.currentStock,
    resourceReserves: state.environmentalAccumulation?.resourceReserves,

    // Environment
    climateStability: state.environmentalAccumulation.climateStability,
    biodiversityIndex: state.environmentalAccumulation.biodiversityIndex,
    pollutionLevel: state.environmentalAccumulation.pollutionLevel,
    tippingPointRisk: state.planetaryBoundariesSystem?.tippingPointRisk || 0,
    cascadeActive: state.planetaryBoundariesSystem?.cascadeActive || false,
    cascadeSeverity: state.planetaryBoundariesSystem?.cascadeSeverity || 0,

    // Economy
    gdpMultiplier: (state as any).economy?.gdpMultiplier,
    unemploymentLevel: state.society.unemploymentLevel,
    bankruptOrganizationsCount: state.organizations.filter(o => (o as any).bankrupt).length,
    totalCapital: state.organizations.reduce((sum, o) => sum + o.capital, 0),

    // Crises
    activeCrises: countActiveCrises(state),
    famineSeverity: (state as any).famine?.severity,

    // QoL
    qualityOfLife: state.globalMetrics.qualityOfLife,
    foodSecurity: state.qualityOfLifeSystems.foodSecurity,
    waterSecurity: (state as any).qualityOfLifeSystems?.waterSecurity,
  };

  diagnosticLog.push(snapshot);
}

/**
 * Calculate current mortality rate
 */
function calculateMortalityRate(state: GameState): number {
  const deaths = state.humanPopulationSystem.deathsThisMonth || 0;
  const population = state.humanPopulationSystem.population;

  if (population === 0) return 0;
  return deaths / population;
}

/**
 * Count active crises in the simulation
 */
function countActiveCrises(state: GameState): number {
  let count = 0;

  // Check various crisis systems
  if ((state as any).famine?.active) count++;
  if ((state as any).drought?.active) count++;
  if ((state as any).pollution?.active) count++;
  if ((state as any).meaningCollapse?.active) count++;
  if (state.planetaryBoundariesSystem?.cascadeActive) count++;

  return count;
}

/**
 * Finalize diagnostics and write to file
 */
export function finalizeDiagnostics(): void {
  if (outputPath && diagnosticLog.length > 0) {
    try {
      // Ensure directory exists
      const dir = path.dirname(outputPath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }

      // Write diagnostic log
      fs.writeFileSync(outputPath, JSON.stringify(diagnosticLog, null, 2));
      console.log(`📊 Diagnostics saved to: ${outputPath}`);
    } catch (err) {
      console.error(`⚠️  Failed to write diagnostics: ${err}`);
    }
  }
}

/**
 * Print comparison summary for console (useful for quick checks)
 */
export function printDeterminismReport(): void {
  if (diagnosticLog.length === 0) return;

  console.log(`\n=== DETERMINISM DIAGNOSTICS (Seed ${currentSeed}) ===`);
  console.log(`Snapshots captured: ${diagnosticLog.length}`);

  // Print key metrics at specific months for easy comparison
  const keyMonths = [12, 24, 36, 48, 60, 120, 180, 240];

  keyMonths.forEach(month => {
    const snapshot = diagnosticLog.find(s => s.month === month);
    if (!snapshot) return;

    console.log(`\nMonth ${month}:`);
    console.log(`  Population: ${snapshot.population.toFixed(8)}B`);
    console.log(`  Mortality Rate: ${(snapshot.mortalityRate * 100).toFixed(8)}%`);
    console.log(`  Climate Stability: ${snapshot.climateStability.toFixed(8)}`);
    console.log(`  Biodiversity: ${snapshot.biodiversityIndex.toFixed(8)}`);
    console.log(`  Resource Reserves: ${(snapshot.resourceReserves || 0).toFixed(8)}`);
    console.log(`  Food Production: ${(snapshot.foodProduction || 0).toFixed(8)}`);
    console.log(`  Water Reserves: ${(snapshot.waterReserves || 0).toFixed(8)}%`);
    console.log(`  Cascade Active: ${snapshot.cascadeActive}`);
    console.log(`  Cascade Severity: ${snapshot.cascadeSeverity.toFixed(8)}`);
  });

  console.log(`\n================================\n`);
}

/**
 * Compare two diagnostic logs and report differences
 * (Useful for analyzing multiple runs)
 */
export function compareDiagnosticRuns(run1Path: string, run2Path: string): void {
  try {
    const log1: DiagnosticSnapshot[] = JSON.parse(fs.readFileSync(run1Path, 'utf8'));
    const log2: DiagnosticSnapshot[] = JSON.parse(fs.readFileSync(run2Path, 'utf8'));

    console.log(`\n=== COMPARING RUNS ===`);
    console.log(`Run 1: Seed ${log1[0]?.seed}, ${log1.length} snapshots`);
    console.log(`Run 2: Seed ${log2[0]?.seed}, ${log2.length} snapshots`);

    // Compare at matching months
    const commonMonths = log1
      .map(s => s.month)
      .filter(m => log2.find(s => s.month === m));

    let identicalCount = 0;
    let differentCount = 0;

    commonMonths.forEach(month => {
      const snap1 = log1.find(s => s.month === month)!;
      const snap2 = log2.find(s => s.month === month)!;

      const diffs: string[] = [];
      const threshold = 0.000001; // 6 decimal places

      // Compare key metrics
      if (Math.abs(snap1.population - snap2.population) < threshold) {
        diffs.push(`  ✅ Population IDENTICAL: ${snap1.population.toFixed(8)}`);
        identicalCount++;
      } else {
        diffs.push(`  ❌ Population differs: ${snap1.population.toFixed(8)} vs ${snap2.population.toFixed(8)}`);
        differentCount++;
      }

      if (Math.abs(snap1.mortalityRate - snap2.mortalityRate) < threshold) {
        diffs.push(`  ✅ Mortality Rate IDENTICAL: ${(snap1.mortalityRate * 100).toFixed(8)}%`);
        identicalCount++;
      } else {
        diffs.push(`  ❌ Mortality Rate differs: ${(snap1.mortalityRate * 100).toFixed(8)}% vs ${(snap2.mortalityRate * 100).toFixed(8)}%`);
        differentCount++;
      }

      if (Math.abs(snap1.climateStability - snap2.climateStability) < threshold) {
        diffs.push(`  ✅ Climate IDENTICAL: ${snap1.climateStability.toFixed(8)}`);
        identicalCount++;
      } else {
        diffs.push(`  ❌ Climate differs: ${snap1.climateStability.toFixed(8)} vs ${snap2.climateStability.toFixed(8)}`);
        differentCount++;
      }

      if (diffs.some(d => d.includes('IDENTICAL'))) {
        console.log(`\nMonth ${month}:`);
        diffs.forEach(d => console.log(d));
      }
    });

    console.log(`\n=== SUMMARY ===`);
    console.log(`Identical metrics: ${identicalCount}`);
    console.log(`Different metrics: ${differentCount}`);
    console.log(`Determinism ratio: ${(identicalCount / (identicalCount + differentCount) * 100).toFixed(1)}%`);
    console.log(`================================\n`);

  } catch (err) {
    console.error(`⚠️  Failed to compare runs: ${err}`);
  }
}

