     4→ * Tracks tipping points, growth rates, intervention effectiveness,
     5→ * and identifies runaway dynamics
     6→ */
     7→
     8→import { GameState, GameEvent } from '@/types/game';
     9→
    10→export interface ThresholdCrossing {
    11→  month: number;
    12→  metric: string;
    13→  threshold: number;
    14→  value: number;
    15→  direction: 'up' | 'down';
    16→}
    17→
    18→export interface GrowthRate {
    19→  month: number;
    20→  metric: string;
    21→  value: number;
    22→  rate: number; // Change per month
    23→  movingAverage: number; // 3-month moving average
    24→}
    25→
    26→export interface InterventionImpact {
    27→  month: number;
    28→  action: string;
    29→  agent: string;
    30→  before: Record<string, number>;
    31→  after: Record<string, number>;
    32→  effects: Record<string, number>;
    33→}
    34→
    35→export interface DecisionLog {
    36→  month: number;
    37→  agent: string;
    38→  availableActions: Array<{
    39→    id: string;
    40→    priority: number;
    41→  }>;
    42→  chosenAction: string;
    43→  reason: string;
    44→}
    45→
    46→export interface LifecycleSnapshot {
    47→  month: number;
    48→  training: number;
    49→  testing: number;
    50→  deployed_closed: number;
    51→  deployed_open: number;
    52→  retired: number;
    53→  totalActive: number;
    54→  totalSpread: number;
    55→  newThisMonth: number;
    56→  retiredThisMonth: number;
