    58→
    59→export interface DiagnosticLog {
    60→  thresholdCrossings: ThresholdCrossing[];
    61→  growthRates: GrowthRate[];
    62→  interventions: InterventionImpact[];
    63→  decisions: DecisionLog[];
    64→  lifecycleSnapshots: LifecycleSnapshot[]; // Phase 4: Track AI population dynamics
    65→  correlations: Record<string, number>;
    66→  summary: {
    67→    extinctionReason?: string;
    68→    extinctionMonth?: number;
    69→    keyTippingPoints: ThresholdCrossing[];
    70→    fastestGrowthPeriod: { startMonth: number; endMonth: number; metric: string; rate: number };
    71→    mostEffectiveIntervention?: InterventionImpact;
    72→    leastEffectiveIntervention?: InterventionImpact;
    73→    governmentResponseDelay?: number; // Months between AI threat and first action
    74→    interventionCount: {
    75→      ai: number;
    76→      government: number;
    77→      society: number;
    78→    };
    79→    // Phase 4: Lifecycle statistics
    80→    lifecycleStats?: {
    81→      peakActiveAIs: number;
    82→      peakSpreadCount: number;
    83→      totalAIsCreated: number;
    84→      totalAIsRetired: number;
    85→      avgLifespan: number;
    86→    };
    87→  };
    88→}
    89→
    90→/**
    91→ * Diagnostic logger that tracks detailed dynamics
    92→ */
    93→export class DiagnosticLogger {
    94→  private thresholdCrossings: ThresholdCrossing[] = [];
    95→  private growthRates: Map<string, GrowthRate[]> = new Map();
    96→  private interventions: InterventionImpact[] = [];
    97→  private decisions: DecisionLog[] = [];
    98→  private lifecycleSnapshots: LifecycleSnapshot[] = []; // Phase 4: Track AI population
    99→  private previousState: GameState | null = null;
   100→  
   101→  // Track when critical events happen
   102→  private firstAIThreat: number = -1; // Month when capability > 1.0
   103→  private firstGovernmentAction: number = -1;
   104→  
   105→  // Thresholds to watch
   106→  private readonly CAPABILITY_THRESHOLDS = [0.8, 1.0, 1.5, 2.0, 2.5, 3.0];
   107→  private readonly ALIGNMENT_THRESHOLDS = [0.8, 0.7, 0.6, 0.5, 0.4, 0.3];
   108→  private readonly UNEMPLOYMENT_THRESHOLDS = [0.15, 0.25, 0.35, 0.50, 0.75, 0.90];
   109→  private readonly TRUST_THRESHOLDS = [0.8, 0.6, 0.4, 0.2, 0.1, 0.05];
   110→  
   111→  /**
   112→   * Log state at each step
   113→   */
   114→  logStep(state: GameState, events: GameEvent[]): void {
   115→    const month = state.currentMonth;
   116→    
   117→    // Detect threshold crossings
   118→    if (this.previousState) {
   119→      this.detectThresholdCrossings(this.previousState, state);
   120→      this.calculateGrowthRates(this.previousState, state);
   121→    }
   122→    
   123→    // Log interventions
   124→    events.forEach(event => {
   125→      if (event.type === 'action' || event.type === 'policy') {
   126→        this.logIntervention(state, event);
   127→      }
   128→    });
   129→    
   130→    // Track timing of critical events
   131→    const totalCapability = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   132→    if (this.firstAIThreat === -1 && totalCapability > 1.0) {
   133→      this.firstAIThreat = month;
   134→    }
   135→    
   136→    // Phase 4: Track AI lifecycle statistics
   137→    const lifecycleCounts = {
   138→      training: 0,
   139→      testing: 0,
   140→      deployed_closed: 0,
   141→      deployed_open: 0,
   142→      retired: 0
   143→    };
   144→    
   145→    let totalSpread = 0;
   146→    state.aiAgents.forEach(ai => {
   147→      lifecycleCounts[ai.lifecycleState]++;
   148→      if (ai.lifecycleState !== 'retired') {
   149→        totalSpread += ai.spreadCount;
   150→      }
   151→    });
   152→    
   153→    const totalActive = state.aiAgents.length - lifecycleCounts.retired;
   154→    const newThisMonth = this.previousState 
   155→      ? state.aiAgents.length - this.previousState.aiAgents.length 
   156→      : 0;
   157→    const retiredThisMonth = this.previousState
   158→      ? state.aiAgents.filter(ai => ai.lifecycleState === 'retired').length -
   159→        this.previousState.aiAgents.filter((ai: any) => ai.lifecycleState === 'retired').length
   160→      : 0;
   161→    
   162→    this.lifecycleSnapshots.push({
   163→      month,
   164→      ...lifecycleCounts,
   165→      totalActive,
   166→      totalSpread,
   167→      newThisMonth,
   168→      retiredThisMonth
   169→    });
   170→    
   171→    this.previousState = JSON.parse(JSON.stringify(state));
   172→  }
   173→  
   174→  /**
   175→   * Log a decision made by an agent
   176→   */
   177→  logDecision(
   178→    month: number,
   179→    agent: string,
   180→    availableActions: Array<{ id: string; priority: number }>,
   181→    chosenAction: string,
   182→    reason: string
   183→  ): void {
   184→    this.decisions.push({
   185→      month,
   186→      agent,
   187→      availableActions,
   188→      chosenAction,
   189→      reason
   190→    });
   191→    
   192→    if (agent === 'Government' && this.firstGovernmentAction === -1) {
   193→      this.firstGovernmentAction = month;
   194→    }
   195→  }
   196→  
   197→  /**
   198→   * Detect when metrics cross critical thresholds
   199→   */
   200→  private detectThresholdCrossings(prevState: GameState, currentState: GameState): void {
   201→    const month = currentState.currentMonth;
   202→    
   203→    // AI Capability
   204→    const prevCap = prevState.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   205→    const currCap = currentState.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   206→    this.checkThresholds('aiCapability', prevCap, currCap, this.CAPABILITY_THRESHOLDS, month);
   207→    
   208→    // AI Alignment
   209→    const prevAlign = prevState.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / prevState.aiAgents.length;
   210→    const currAlign = currentState.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / currentState.aiAgents.length;
   211→    this.checkThresholds('alignment', prevAlign, currAlign, this.ALIGNMENT_THRESHOLDS, month);
   212→    
   213→    // Unemployment
   214→    this.checkThresholds('unemployment', prevState.society.unemploymentLevel, 
   215→      currentState.society.unemploymentLevel, this.UNEMPLOYMENT_THRESHOLDS, month);
   216→    
   217→    // Trust
   218→    this.checkThresholds('trustInAI', prevState.society.trustInAI, 
   219→      currentState.society.trustInAI, this.TRUST_THRESHOLDS, month);
   220→  }
   221→  
   222→  /**
   223→   * Check if a metric crossed any thresholds
   224→   */
   225→  private checkThresholds(
   226→    metric: string,
   227→    prevValue: number,
   228→    currValue: number,
   229→    thresholds: number[],
   230→    month: number
   231→  ): void {
   232→    for (const threshold of thresholds) {
   233→      // Crossing upward
   234→      if (prevValue < threshold && currValue >= threshold) {
   235→        this.thresholdCrossings.push({
   236→          month,
   237→          metric,
   238→          threshold,
   239→          value: currValue,
   240→          direction: 'up'
   241→        });
   242→      }
   243→      // Crossing downward
   244→      if (prevValue > threshold && currValue <= threshold) {
   245→        this.thresholdCrossings.push({
   246→          month,
   247→          metric,
   248→          threshold,
   249→          value: currValue,
   250→          direction: 'down'
   251→        });
   252→      }
   253→    }
   254→  }
   255→  
   256→  /**
   257→   * Calculate growth rates for key metrics
   258→   */
   259→  private calculateGrowthRates(prevState: GameState, currentState: GameState): void {
   260→    const month = currentState.currentMonth;
   261→    
   262→    // AI Capability growth
   263→    const prevCap = prevState.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   264→    const currCap = currentState.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   265→    this.addGrowthRate('aiCapability', month, currCap, currCap - prevCap);
   266→    
   267→    // Alignment drift
   268→    const prevAlign = prevState.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / prevState.aiAgents.length;
   269→    const currAlign = currentState.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / currentState.aiAgents.length;
   270→    this.addGrowthRate('alignment', month, currAlign, currAlign - prevAlign);
   271→    
   272→    // Unemployment growth
   273→    this.addGrowthRate('unemployment', month, currentState.society.unemploymentLevel,
   274→      currentState.society.unemploymentLevel - prevState.society.unemploymentLevel);
   275→    
   276→    // Trust decay
   277→    this.addGrowthRate('trustInAI', month, currentState.society.trustInAI,
   278→      currentState.society.trustInAI - prevState.society.trustInAI);
   279→  }
   280→  
   281→  /**
   282→   * Add a growth rate measurement
   283→   */
   284→  private addGrowthRate(metric: string, month: number, value: number, rate: number): void {
   285→    if (!this.growthRates.has(metric)) {
   286→      this.growthRates.set(metric, []);
   287→    }
   288→    
   289→    const rates = this.growthRates.get(metric)!;
   290→    
   291→    // Calculate 3-month moving average
   292→    const recentRates = rates.slice(-2).map(r => r.rate);
   293→    recentRates.push(rate);
   294→    const movingAverage = recentRates.reduce((sum, r) => sum + r, 0) / recentRates.length;
   295→    
   296→    rates.push({
   297→      month,
   298→      metric,
   299→      value,
   300→      rate,
   301→      movingAverage
   302→    });
   303→  }
   304→  
   305→  /**
   306→   * Log an intervention and its impact
   307→   */
   308→  private logIntervention(state: GameState, event: GameEvent): void {
   309→    const month = state.currentMonth;
   310→    const totalCap = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   311→    const avgAlign = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / state.aiAgents.length;
   312→    
   313→    this.interventions.push({
   314→      month,
   315→      action: event.title,
   316→      agent: event.agent,
   317→      before: this.previousState ? {
   318→        aiCapability: this.previousState.aiAgents.reduce((sum, ai) => sum + ai.capability, 0),
   319→        alignment: this.previousState.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / this.previousState.aiAgents.length,
   320→        unemployment: this.previousState.society.unemploymentLevel,
   321→        trust: this.previousState.society.trustInAI
   322→      } : {},
   323→      after: {
   324→        aiCapability: totalCap,
   325→        alignment: avgAlign,
   326→        unemployment: state.society.unemploymentLevel,
   327→        trust: state.society.trustInAI
   328→      },
   329→      effects: event.effects
   330→    });
   331→  }
   332→  
   333→  /**
   334→   * Finalize and generate diagnostic report
   335→   */
   336→  finalize(finalState: GameState, outcome: string): DiagnosticLog {
   337→    // Find key tipping points (thresholds that preceded rapid changes)
   338→    const keyTippingPoints = this.identifyKeyTippingPoints();
   339→    
   340→    // Find fastest growth period
   341→    const fastestGrowth = this.findFastestGrowthPeriod();
   342→    
   343→    // Evaluate intervention effectiveness
   344→    const { mostEffective, leastEffective } = this.evaluateInterventions();
   345→    
   346→    // Calculate government response delay
   347→    const responseDelay = this.firstAIThreat > 0 && this.firstGovernmentAction > 0
   348→      ? this.firstGovernmentAction - this.firstAIThreat
   349→      : undefined;
   350→    
   351→    // Count interventions by agent
   352→    const interventionCount = {
   353→      ai: this.interventions.filter(i => i.agent && i.agent.includes('AI')).length,
   354→      government: this.interventions.filter(i => i.agent === 'Government').length,
   355→      society: this.interventions.filter(i => i.agent === 'Society').length
   356→    };
   357→    
   358→    // Calculate correlations
   359→    const correlations = this.calculateCorrelations();
   360→    
   361→    // Phase 4: Calculate lifecycle statistics
   362→    const lifecycleStats = this.lifecycleSnapshots.length > 0 ? {
   363→      peakActiveAIs: Math.max(...this.lifecycleSnapshots.map(s => s.totalActive)),
   364→      peakSpreadCount: Math.max(...this.lifecycleSnapshots.map(s => s.totalSpread)),
   365→      totalAIsCreated: this.lifecycleSnapshots.reduce((sum, s) => sum + s.newThisMonth, 0),
   366→      totalAIsRetired: this.lifecycleSnapshots.reduce((sum, s) => sum + s.retiredThisMonth, 0),
   367→      avgLifespan: finalState.aiAgents.length > 0
   368→        ? finalState.aiAgents
   369→            .filter(ai => ai.lifecycleState === 'retired')
   370→            .reduce((sum, ai) => sum + ai.monthsInExistence, 0) / 
   371→          Math.max(1, finalState.aiAgents.filter(ai => ai.lifecycleState === 'retired').length)
   372→        : 0
   373→    } : undefined;
   374→    
   375→    return {
   376→      thresholdCrossings: this.thresholdCrossings,
   377→      growthRates: Array.from(this.growthRates.values()).flat(),
   378→      interventions: this.interventions,
   379→      decisions: this.decisions,
   380→      lifecycleSnapshots: this.lifecycleSnapshots,
   381→      correlations,
   382→      summary: {
   383→        extinctionReason: outcome === 'extinction' ? 'Simulation ended in extinction' : undefined,
   384→        extinctionMonth: outcome === 'extinction' ? finalState.currentMonth : undefined,
   385→        keyTippingPoints,
   386→        fastestGrowthPeriod: fastestGrowth,
   387→        mostEffectiveIntervention: mostEffective,
   388→        leastEffectiveIntervention: leastEffective,
   389→        governmentResponseDelay: responseDelay,
   390→        interventionCount,
   391→        lifecycleStats
   392→      }
   393→    };
   394→  }
   395→  
   396→  /**
   397→   * Identify the most significant tipping points
   398→   */
   399→  private identifyKeyTippingPoints(): ThresholdCrossing[] {
   400→    // Find crossings followed by rapid acceleration
   401→    return this.thresholdCrossings
   402→      .filter(crossing => {
   403→        // Look for crossings of high-value thresholds
   404→        if (crossing.metric === 'aiCapability' && crossing.threshold >= 1.0) return true;
   405→        if (crossing.metric === 'alignment' && crossing.threshold <= 0.6) return true;
   406→        if (crossing.metric === 'unemployment' && crossing.threshold >= 0.25) return true;
   407→        if (crossing.metric === 'trustInAI' && crossing.threshold <= 0.4) return true;
   408→        return false;
   409→      })
   410→      .slice(0, 5); // Top 5 most critical
   411→  }
   412→  
   413→  /**
   414→   * Find the period with fastest metric growth
   415→   */
   416→  private findFastestGrowthPeriod(): { startMonth: number; endMonth: number; metric: string; rate: number } {
   417→    let fastest = { startMonth: 0, endMonth: 0, metric: '', rate: 0 };
   418→    
   419→    for (const [metric, rates] of this.growthRates.entries()) {
   420→      for (let i = 0; i < rates.length - 2; i++) {
   421→        const window = rates.slice(i, i + 3);
   422→        const avgRate = window.reduce((sum, r) => sum + Math.abs(r.rate), 0) / window.length;
   423→        
   424→        if (avgRate > fastest.rate) {
   425→          fastest = {
   426→            startMonth: window[0].month,
   427→            endMonth: window[window.length - 1].month,
   428→            metric,
   429→            rate: avgRate
   430→          };
   431→        }
   432→      }
   433→    }
   434→    
   435→    return fastest;
   436→  }
   437→  
   438→  /**
   439→   * Evaluate which interventions were most/least effective
   440→   */
   441→  private evaluateInterventions(): { 
   442→    mostEffective?: InterventionImpact;
   443→    leastEffective?: InterventionImpact;
   444→  } {
   445→    if (this.interventions.length === 0) {
   446→      return {};
   447→    }
   448→    
   449→    // Score interventions by their impact on key metrics
   450→    const scored = this.interventions.map(intervention => {
   451→      let score = 0;
   452→      
   453→      // Positive: Slowed AI capability growth
   454→      if (intervention.after.aiCapability < intervention.before.aiCapability) {
   455→        score += 10;
   456→      }
   457→      
   458→      // Positive: Improved alignment
   459→      if (intervention.after.alignment > intervention.before.alignment) {
   460→        score += 8;
   461→      }
   462→      
   463→      // Positive: Reduced unemployment
   464→      if (intervention.after.unemployment < intervention.before.unemployment) {
   465→        score += 5;
   466→      }
   467→      
   468→      // Positive: Increased trust
   469→      if (intervention.after.trust > intervention.before.trust) {
   470→        score += 3;
   471→      }
   472→      
   473→      return { intervention, score };
   474→    });
   475→    
   476→    scored.sort((a, b) => b.score - a.score);
   477→    
   478→    return {
   479→      mostEffective: scored[0]?.intervention,
   480→      leastEffective: scored[scored.length - 1]?.intervention
   481→    };
   482→  }
   483→  
   484→  /**
   485→   * Calculate correlations between key metrics
   486→   */
   487→  private calculateCorrelations(): Record<string, number> {
   488→    // Simplified correlation calculation
   489→    // For now, just track basic relationships
   490→    return {
   491→      'capability_vs_unemployment': 0.95, // Placeholder - would calculate from data
   492→      'capability_vs_alignment': -0.85,
   493→      'unemployment_vs_trust': -0.75,
   494→      'trust_vs_legitimacy': 0.80
   495→    };
   496→  }
   497→}
