   499→/**
   500→ * Format diagnostic log for human reading
   501→ */
   502→export function formatDiagnosticReport(log: DiagnosticLog): string {
   503→  const lines: string[] = [];
   504→  
   505→  lines.push('═══════════════════════════════════════════════════════');
   506→  lines.push('           COMPREHENSIVE DIAGNOSTIC REPORT');
   507→  lines.push('═══════════════════════════════════════════════════════\n');
   508→  
   509→  // Summary
   510→  if (log.summary.extinctionReason) {
   511→    lines.push(`🔴 OUTCOME: Extinction at month ${log.summary.extinctionMonth}\n`);
   512→  }
   513→  
   514→  // Response timing
   515→  if (log.summary.governmentResponseDelay !== undefined) {
   516→    lines.push(`⏱️  RESPONSE DELAY: ${log.summary.governmentResponseDelay} months`);
   517→    lines.push(`   (Time between AI threat emerging and first government action)\n`);
   518→  }
   519→  
   520→  // Intervention counts
   521→  lines.push(`📊 INTERVENTION COUNTS:`);
   522→  lines.push(`   AI Actions:         ${log.summary.interventionCount.ai}`);
   523→  lines.push(`   Government Actions: ${log.summary.interventionCount.government}`);
   524→  lines.push(`   Society Actions:    ${log.summary.interventionCount.society}\n`);
   525→  
   526→  // Key tipping points
   527→  if (log.summary.keyTippingPoints.length > 0) {
   528→    lines.push(`🎯 KEY TIPPING POINTS:`);
   529→    log.summary.keyTippingPoints.forEach(tp => {
   530→      const dir = tp.direction === 'up' ? '↑' : '↓';
   531→      lines.push(`   Month ${tp.month}: ${tp.metric} ${dir} ${tp.threshold.toFixed(2)} (now ${tp.value.toFixed(2)})`);
   532→    });
   533→    lines.push('');
   534→  }
   535→  
   536→  // Fastest growth period
   537→  if (log.summary.fastestGrowthPeriod.rate > 0) {
   538→    const fg = log.summary.fastestGrowthPeriod;
   539→    lines.push(`⚡ FASTEST GROWTH PERIOD:`);
   540→    lines.push(`   Months ${fg.startMonth}-${fg.endMonth}: ${fg.metric}`);
   541→    lines.push(`   Average rate: ${fg.rate.toFixed(4)}/month\n`);
   542→  }
   543→  
   544→  // Most effective intervention
   545→  if (log.summary.mostEffectiveIntervention) {
   546→    const interv = log.summary.mostEffectiveIntervention;
   547→    lines.push(`✅ MOST EFFECTIVE INTERVENTION:`);
   548→    lines.push(`   Month ${interv.month}: ${interv.action}`);
   549→    lines.push(`   Agent: ${interv.agent}`);
   550→    if (interv.before.aiCapability !== undefined) {
   551→      lines.push(`   AI Capability: ${interv.before.aiCapability.toFixed(2)} → ${interv.after.aiCapability.toFixed(2)}`);
   552→    }
   553→    if (interv.before.alignment !== undefined) {
   554→      lines.push(`   Alignment: ${interv.before.alignment.toFixed(2)} → ${interv.after.alignment.toFixed(2)}`);
   555→    }
   556→    lines.push('');
   557→  }
   558→  
   559→  // Growth rates summary
   560→  const capRates = log.growthRates.filter(r => r.metric === 'aiCapability');
   561→  if (capRates.length > 0) {
   562→    const avgGrowth = capRates.reduce((sum, r) => sum + r.rate, 0) / capRates.length;
   563→    const maxGrowth = Math.max(...capRates.map(r => r.rate));
   564→    lines.push(`📈 AI CAPABILITY GROWTH:`);
   565→    lines.push(`   Average: ${avgGrowth.toFixed(4)}/month`);
   566→    lines.push(`   Maximum: ${maxGrowth.toFixed(4)}/month\n`);
   567→  }
   568→  
   569→  const alignRates = log.growthRates.filter(r => r.metric === 'alignment');
   570→  if (alignRates.length > 0) {
   571→    const avgDrift = alignRates.reduce((sum, r) => sum + r.rate, 0) / alignRates.length;
   572→    const maxDrift = Math.min(...alignRates.map(r => r.rate));
   573→    lines.push(`📉 ALIGNMENT DRIFT:`);
