   233→  const baselineDeaths = pop.baselineDeathRate * healthcareReduction * warMultiplier;
   234→  
   235→  // NEW: Environmental mortality ADDS to baseline (not multiplies)
   236→  // This is because environmental deaths are additional excess mortality
   237→  pop.adjustedDeathRate = baselineDeaths + (envMortality.total * 12); // Convert monthly to annual
   238→  
   239→  // === 4. APPLY EXTINCTION SCENARIO IMPACTS (Non-Environmental) ===
   240→  // Nuclear war, AI takeover, etc. - still use old extinction logic
   241→  if (state.extinctionState.active && state.extinctionState.mechanism !== 'climate_tipping_point') {
   242→    const extinctionDeathRate = calculateExtinctionDeathRate(state);
   243→    pop.adjustedDeathRate += extinctionDeathRate;
   244→  }
   245→  // Note: Environmental extinction is now handled by calculateEnvironmentalMortality()
   246→
   247→  // === 5. CALCULATE NET GROWTH ===
   248→  pop.netGrowthRate = pop.adjustedBirthRate - pop.adjustedDeathRate;
   249→  const monthlyGrowthRate = pop.netGrowthRate / 12;
   250→
   251→  // === 6. APPLY POPULATION CHANGE ===
   252→  const previousPopulation = pop.population;
   253→  const newPopulation = pop.population * (1 + monthlyGrowthRate);
   254→
   255→  // Guard against NaN
   256→  if (isNaN(newPopulation) || newPopulation < 0) {
   257→    console.warn(`⚠️  Population calculation produced ${newPopulation}, using previous value`);
   258→    pop.population = Math.max(0, previousPopulation * 0.99); // Small decline as fallback
   259→  } else {
   260→    pop.population = Math.max(0, newPopulation);
   261→  }
   262→
   263→  // === 7. CARRYING CAPACITY CONSTRAINT ===
   264→  // Overshoot → die-off (Malthusian collapse)
   265→  if (pop.population > pop.carryingCapacity) {
   266→    const overshoot = pop.population - pop.carryingCapacity;
   267→    const overshootDeaths = overshoot * 0.05; // 5% of excess dies per month
   268→    pop.population -= overshootDeaths;
   269→    pop.monthlyExcessDeaths += overshootDeaths;
   270→    // FIX P1.1: Convert overshoot deaths from billions to millions for consistency
   271→    pop.deathsByCategory.famine += overshootDeaths * 1000; // Track overshoot deaths as famine (in millions)
   272→  }
   273→
   274→  // === 8. TRACK CUMULATIVE DEATHS ===
   275→  const naturalDeaths = previousPopulation * (pop.baselineDeathRate / 12);
   276→  const actualDeaths = previousPopulation - pop.population;
   277→  pop.monthlyExcessDeaths = Math.max(0, actualDeaths - naturalDeaths);
   278→  pop.cumulativeCrisisDeaths += pop.monthlyExcessDeaths;
   279→
   280→  // FIX (Oct 13, 2025): Track environmental deaths by category
   281→  // This fixes the "90% of deaths missing" bug in Monte Carlo reports
   282→  // Environmental mortality is a rate (0-0.10), applied to current population
   283→  const currentPopBillions = previousPopulation; // Use pop at START of month
   284→  pop.deathsByCategory.famine += (envMortality.famine * currentPopBillions * 1000); // Convert to millions
   285→  pop.deathsByCategory.disease += (envMortality.disease * currentPopBillions * 1000);
   286→  pop.deathsByCategory.climate += (envMortality.climate * currentPopBillions * 1000);
   287→  pop.deathsByCategory.ecosystem += (envMortality.ecosystem * currentPopBillions * 1000);
   288→  pop.deathsByCategory.pollution += (envMortality.pollution * currentPopBillions * 1000);
   289→
   290→  // DEBUG (P1.1 - Death Accounting): Log death tracking mismatch
   291→  if (state.currentMonth % 12 === 0 && actualDeaths > 0.1) { // Log annually when deaths >100M
   292→    const trackedDeaths = Object.values(pop.deathsByCategory).reduce((a, b) => a + b, 0) / 1000; // Convert millions to billions
   293→    const discrepancy = Math.abs(actualDeaths - trackedDeaths);
   294→    if (discrepancy > 0.5) { // >500M discrepancy
   295→      console.log(`⚠️  DEATH ACCOUNTING MISMATCH (Month ${state.currentMonth}):`);
   296→      console.log(`   Actual population deaths: ${actualDeaths.toFixed(3)}B (${(actualDeaths * 1000).toFixed(0)}M)`);
   297→      console.log(`   Tracked by category: ${trackedDeaths.toFixed(3)}B (${(trackedDeaths * 1000).toFixed(0)}M)`);
   298→      console.log(`   Discrepancy: ${discrepancy.toFixed(3)}B (${(discrepancy * 1000).toFixed(0)}M) - ${(discrepancy / actualDeaths * 100).toFixed(0)}%`);
   299→      console.log(`   Categories: war=${(pop.deathsByCategory.war).toFixed(0)}M, famine=${(pop.deathsByCategory.famine).toFixed(0)}M, climate=${(pop.deathsByCategory.climate).toFixed(0)}M`);
   300→    }
   301→  }
   302→
   303→  // === 9. CHECK THRESHOLDS ===
   304→  pop.geneticBottleneckActive = pop.population < (pop.bottleneckThreshold / 1000000000); // Convert to billions
   305→
   306→  // === 10. UPDATE PEAK TRACKING ===
   307→  if (pop.population > pop.peakPopulation) {
   308→    pop.peakPopulation = pop.population;
   309→    pop.peakPopulationMonth = state.currentMonth;
   310→  }
   311→
   312→  // === 11. RECOVERY POTENTIAL ===
   313→  pop.canRecover =
   314→    pop.population > (pop.bottleneckThreshold / 1000000000) && // Above bottleneck
   315→    pop.populationPressure < 0.8 && // Room to grow
   316→    !state.extinctionState.active && // No active extinction
   317→    state.globalMetrics.socialStability > 0.3; // Society functions
   318→
   319→  if (pop.canRecover && pop.netGrowthRate < 0) {
   320→    // Slow recovery growth (0.5-1% per year)
   321→    pop.recoveryRate = 0.005 * pop.capacityModifier;
   322→    pop.population *= (1 + pop.recoveryRate / 12);
   323→  } else {
   324→    pop.recoveryRate = 0;
   325→  }
   326→
   327→  // === 12. UPDATE DEMOGRAPHICS ===
   328→  updateDemographics(state);
   329→
   330→  // === 13. DETECT CRITICAL EVENTS ===
   331→  detectPopulationEvents(state);
   332→}
