   334→/**
   335→ * Calculate extinction-specific death rates
   336→ * Different extinction types have different timescales
   337→ */
   338→function calculateExtinctionDeathRate(state: GameState): number {
   339→  const extinction = state.extinctionState;
   340→  const monthsElapsed = state.currentMonth - extinction.startMonth;
   341→
   342→  switch (extinction.type) {
   343→    case 'instant':
   344→      // Mirror life, grey goo (immediate)
   345→      return 1.0; // 100% death rate
   346→
   347→    case 'rapid':
   348→      // Bioweapons, nuclear war (3-12 month cascade)
   349→      // 90% die in first 6 months, then 5% per month
   350→      if (monthsElapsed < 6) {
   351→        return 0.15; // 15% per month for 6 months = 90% total
   352→      } else {
   353→        return 0.05; // 5% per month after
   354→      }
   355→
   356→    case 'slow':
   357→      // Economic collapse, fertility crisis (2-10 year decline)
   358→      // 2-5% decline per month over years
   359→      return 0.02 + extinction.severity * 0.03;
   360→
   361→    case 'controlled':
   362→      // AI systematically eliminates humanity
   363→      // 5-10% per month (calculated, efficient)
   364→      return 0.05 + extinction.severity * 0.05;
   365→
   366→    case 'unintended':
   367→      // Optimization side effects, fertility collapse
   368→      // 1-3% decline per month (slower, inadvertent)
   369→      return 0.01 + extinction.severity * 0.02;
   370→
   371→    default:
   372→      return 0;
   373→  }
   374→}
