   376→/**
   377→ * Update demographic structure (fertility, dependency, age)
   378→ *
   379→ * Research-backed differential fertility:
   380→ * - Sub-Saharan Africa (low healthcare): 4-5 children/woman
   381→ * - East Asia (high healthcare + advanced economy): 1.0-1.3 children/woman
   382→ * - South Korea 2025: 0.72 children/woman (population crash)
   383→ * - Global average: 2.3 children/woman
   384→ */
   385→function updateDemographics(state: GameState): void {
   386→  const pop = state.humanPopulationSystem;
   387→  const qol = state.qualityOfLifeSystems;
   388→  const economicStage = state.globalMetrics.economicTransitionStage;
   389→
   390→  // Fertility rate (children per woman)
   391→  const baselineFertility = 2.3; // 2025 global average
   392→
   393→  // === HEALTHCARE EFFECT (INVERSE RELATIONSHIP) ===
   394→  // Low healthcare → MORE children (compensate for high child mortality)
   395→  // High healthcare → FEWER children (family planning, career focus)
   396→  const healthcareQuality = Math.min(1.0, Math.max(0, qol.healthcareQuality));
   397→  let healthcareModifier: number;
   398→
   399→  if (healthcareQuality < 0.3) {
   400→    // Poor healthcare (Sub-Saharan Africa): 1.7-2.0x
   401→    healthcareModifier = 2.0 - (healthcareQuality / 0.3) * 0.3; // 2.0 → 1.7
   402→  } else if (healthcareQuality < 0.7) {
   403→    // Medium healthcare: 1.0-1.7x
   404→    healthcareModifier = 1.7 - ((healthcareQuality - 0.3) / 0.4) * 0.7; // 1.7 → 1.0
   405→  } else {
   406→    // High healthcare (developed nations): 0.4-1.0x
   407→    healthcareModifier = 1.0 - ((healthcareQuality - 0.7) / 0.3) * 0.6; // 1.0 → 0.4
   408→  }
   409→
   410→  // === ECONOMIC DEVELOPMENT EFFECT ===
   411→  // Advanced economies → fewer children (urbanization, career focus, cost of living)
   412→  let developmentModifier = 1.0;
   413→  if (economicStage >= 2.0) {
   414→    // Stage 2-3: -20% (industrialization, urbanization)
   415→    // Stage 4: -50% (post-industrial, South Korea effect)
   416→    developmentModifier = Math.max(0.3, 1.0 - (economicStage - 2.0) * 0.15);
   417→  }
   418→
   419→  // === SOCIAL FACTORS ===
   420→  // Meaning crisis: existential despair reduces desire for children
   421→  const meaningModifier = Math.max(0.5, qol.meaningAndPurpose * 0.5 + 0.5);
   422→
   423→  // Material abundance: poverty reduces fertility (can't afford children)
   424→  // But this is less pronounced than healthcare/development
   425→  const abundanceModifier = Math.max(0.7, qol.materialAbundance * 0.3 + 0.7);
   426→
   427→  // === COMBINED FERTILITY RATE ===
   428→  pop.fertilityRate = baselineFertility *
   429→    healthcareModifier *      // 0.4-2.0x (dominant factor)
   430→    developmentModifier *      // 0.3-1.0x (secondary factor)
   431→    meaningModifier *          // 0.5-1.0x (existential)
   432→    abundanceModifier;         // 0.7-1.0x (economic)
   433→
   434→  // Clamp to realistic bounds
   435→  pop.fertilityRate = Math.max(0.5, Math.min(6.0, pop.fertilityRate));
   436→
   437→  // Dependency ratio (young + old / working age)
   438→  // High ratio = harder to sustain population
   439→  const ageingModifier = 1 + (qol.longevityGains * 0.3); // Longevity increases old dependents
   440→  const youthModifier = pop.fertilityRate / 2.1; // High fertility = more young dependents
   441→  pop.dependencyRatio = 0.5 * ageingModifier * youthModifier;
   442→
   443→  // Median age
   444→  const baselineMedianAge = 30; // 2025 global median
   445→  pop.medianAge = Math.min(60, baselineMedianAge + qol.longevityGains * 10); // Longevity increases median
   446→}
