   451→function detectPopulationEvents(state: GameState): void {
   452→  const pop = state.humanPopulationSystem;
   453→  const status = getPopulationStatus(pop.population);
   454→  const decline = ((pop.peakPopulation - pop.population) / pop.peakPopulation) * 100;
   455→
   456→  // Log major thresholds crossed
   457→  if (status === PopulationStatus.DECLINING && decline > 10) {
   458→    if (state.currentMonth % 12 === 0) { // Log once per year
   459→      console.log(`⚠️ POPULATION DECLINE: ${pop.population.toFixed(2)}B (${decline.toFixed(0)}% from peak)`);
   460→    }
   461→  }
   462→
   463→  if (status === PopulationStatus.CRITICAL && !pop.geneticBottleneckActive) {
   464→    console.log(`🚨 CRITICAL POPULATION CRASH: ${(pop.population * 1000).toFixed(0)}M remaining`);
   465→    console.log(`   Infrastructure collapse imminent`);
   466→  }
   467→
   468→  if (status === PopulationStatus.BOTTLENECK && !pop.geneticBottleneckActive) {
   469→    pop.geneticBottleneckActive = true;
   470→    console.log(`☠️ GENETIC BOTTLENECK: ${(pop.population * 1000000).toFixed(0)} humans survive`);
   471→    console.log(`   Permanent loss of genetic diversity`);
   472→    console.log(`   Recovery uncertain`);
   473→  }
   474→
   475→  if (status === PopulationStatus.EXTINCTION) {
