   489→/**
   490→ * Get population status based on current population
   491→ */
   492→export function getPopulationStatus(population: number): PopulationStatus {
   493→  const popMillions = population * 1000; // Convert billions to millions
   494→
   495→  if (popMillions >= 7000) return PopulationStatus.THRIVING;
   496→  if (popMillions >= 5000) return PopulationStatus.STABLE;
   497→  if (popMillions >= 2000) return PopulationStatus.DECLINING;
   498→  if (popMillions >= 100) return PopulationStatus.CRITICAL;
   499→  if (popMillions >= 0.01) return PopulationStatus.BOTTLENECK; // 10K
   500→  return PopulationStatus.EXTINCTION;
   501→}
