   503→/**
   504→ * Determine final population outcome for end-game reporting
   505→ */
   506→export function determinePopulationOutcome(state: GameState): PopulationOutcome {
   507→  const pop = state.humanPopulationSystem;
   508→  const status = getPopulationStatus(pop.population);
   509→  const decline = ((pop.peakPopulation - pop.population) / pop.peakPopulation) * 100;
   510→
   511→  let narrative: string;
   512→  let civilizationIntact: boolean;
   513→
   514→  switch (status) {
   515→    case PopulationStatus.THRIVING:
   516→      narrative = `Humanity thrives at ${(pop.population).toFixed(2)}B people. Civilization flourishes.`;
   517→      civilizationIntact = true;
   518→      break;
   519→
   520→    case PopulationStatus.STABLE:
   521→      narrative = `Population stabilized at ${(pop.population).toFixed(2)}B (${decline.toFixed(0)}% decline from peak). Society adapts to new equilibrium.`;
   522→      civilizationIntact = true;
   523→      break;
   524→
   525→    case PopulationStatus.DECLINING:
   526→      narrative = `Severe population crash: ${(pop.population).toFixed(2)}B remaining (${decline.toFixed(0)}% loss). Civilization struggles but survives.`;
   527→      civilizationIntact = true;
   528→      break;
   529→
   530→    case PopulationStatus.CRITICAL:
   531→      const popMillions = (pop.population * 1000).toFixed(0);
   532→      narrative = `Catastrophic collapse: Only ${popMillions}M humans remain (${decline.toFixed(0)}% loss). Infrastructure crumbling. Dark ages likely.`;
   533→      civilizationIntact = false;
   534→      break;
   535→
   536→    case PopulationStatus.BOTTLENECK:
   537→      const popThousands = (pop.population * 1000000).toFixed(0);
   538→      narrative = `Near-extinction event: Fewer than ${popThousands} humans survive. Genetic bottleneck. Recovery uncertain.`;
   539→      civilizationIntact = false;
   540→      break;
   541→
   542→    case PopulationStatus.EXTINCTION:
   543→      narrative = `Human extinction. Last humans died in month ${state.currentMonth}. Final population: ${(pop.population * 1000000).toFixed(0)} individuals.`;
   544→      civilizationIntact = false;
   545→      break;
   546→  }
   547→
   548→  return {
   549→    status,
   550→    finalPopulation: pop.population,
   551→    peakPopulation: pop.peakPopulation,
   552→    populationDecline: decline,
   553→    geneticBottleneck: pop.geneticBottleneckActive,
   554→    civilizationIntact,
   555→    outcomeNarrative: narrative
   556→  };
   557→}
