   559→/**
   560→ * Add acute crisis deaths from specific events
   561→ * (Nuclear war, major disasters, famine, etc.)
   562→ *
   563→ * REGIONAL VS GLOBAL DISTINCTION:
   564→ * - Regional crises: Affect only exposed fraction of world (state collapse, local famine, riots)
   565→ * - Global crises: Affect entire world population (ocean acidification, microplastics, nuclear winter)
   566→ *
   567→ * @param state Game state
   568→ * @param mortalityRate Death rate within exposed population (e.g., 0.60 = 60% die)
   569→ * @param reason Short description for logging
   570→ * @param exposedFraction Fraction of world population exposed [0-1] (default 1.0 = global)
   571→ * @param category Death category for tracking (default 'other')
   572→ */
   573→export function addAcuteCrisisDeaths(
   574→  state: GameState,
   575→  mortalityRate: number,
   576→  reason: string,
   577→  exposedFraction: number = 1.0,
   578→  category: 'war' | 'famine' | 'climate' | 'disease' | 'ecosystem' | 'pollution' | 'ai' | 'other' = 'other'
   579→): void {
   580→  const pop = state.humanPopulationSystem;
   581→
   582→  // Guard against NaN/invalid inputs
   583→  if (isNaN(mortalityRate) || mortalityRate < 0 || mortalityRate > 1) {
   584→    console.warn(`⚠️  Invalid mortality rate: ${mortalityRate} for ${reason}`);
   585→    return;
   586→  }
   587→
   588→  if (isNaN(exposedFraction) || exposedFraction < 0 || exposedFraction > 1) {
   589→    console.warn(`⚠️  Invalid exposure fraction: ${exposedFraction} for ${reason}`);
   590→    return;
   591→  }
   592→
   593→  if (isNaN(pop.population)) {
   594→    console.warn(`⚠️  Population is NaN before crisis deaths (${reason}), resetting to 0.1B`);
   595→    pop.population = 0.1; // Small survival population as fallback
   596→  }
   597→
   598→  // Calculate deaths: Only exposed population × mortality rate
   599→  const exposedPopulation = pop.population * exposedFraction;
   600→  const deathsInBillions = exposedPopulation * mortalityRate;
   601→
   602→  // Apply immediate deaths
   603→  pop.population = Math.max(0, pop.population - deathsInBillions);
   604→  pop.monthlyExcessDeaths += deathsInBillions;
   605→  pop.cumulativeCrisisDeaths += deathsInBillions;
   606→
   607→  // Track by category (FIX P1.1: Convert to millions for consistency with environmental deaths)
   608→  pop.deathsByCategory[category] += deathsInBillions * 1000; // Convert billions to millions
   609→
   610→  // Log significant events
   611→  if (deathsInBillions > 0.001) { // > 1M deaths
   612→    const deathsInMillions = (deathsInBillions * 1000).toFixed(1);
   613→    const exposedPct = (exposedFraction * 100).toFixed(0);
   614→    const scope = exposedFraction >= 0.9 ? 'GLOBAL' : exposedFraction >= 0.4 ? 'SEMI-GLOBAL' : 'REGIONAL';
   615→    console.log(`💀 ${scope} CRISIS DEATHS: ${deathsInMillions}M casualties (${reason}) [${category.toUpperCase()}]`);
   616→    console.log(`   Exposed: ${exposedPct}% of world, Mortality: ${(mortalityRate * 100).toFixed(1)}%`);
   617→    console.log(`   Population: ${pop.population.toFixed(3)}B remaining`);
   618→  }
   619→}
