   644→/**
   645→ * Apply population effects to Quality of Life systems
   646→ * Population dynamics create feedback loops on QoL
   647→ */
   648→export function applyPopulationEffectsToQoL(state: GameState): void {
   649→  const pop = state.humanPopulationSystem;
   650→  const qol = state.qualityOfLifeSystems;
   651→
   652→  // Overpopulation stress
   653→  if (pop.populationPressure > 1.0) {
   654→    const overpopulationStress = (pop.populationPressure - 1.0) * 0.5;
   655→    qol.materialAbundance *= (1 - overpopulationStress * 0.3);
   656→    qol.physicalSafety *= (1 - overpopulationStress * 0.2);
   657→    qol.mentalHealth *= (1 - overpopulationStress * 0.1);
   658→  }
   659→
   660→  // Population collapse trauma
   661→  const declineRate = Math.abs(Math.min(0, pop.netGrowthRate));
   662→  if (declineRate > 0.01) { // >1% decline per year
   663→    qol.mentalHealth *= (1 - declineRate * 5); // Mass trauma
   664→    qol.meaningAndPurpose *= (1 - declineRate * 3); // Existential crisis
   665→    qol.socialConnection *= (1 - declineRate * 2); // Communities shattered
   666→  }
   667→
   668→  // Genetic bottleneck effects
   669→  if (pop.geneticBottleneckActive) {
   670→    qol.healthcareQuality *= 0.5; // Loss of medical knowledge
   671→    qol.diseasesBurden *= 2.0; // Higher disease susceptibility
   672→    qol.longevityGains *= 0.3; // Life expectancy plummets
   673→  }
   674→}
