   676→/**
   677→ * Update outcome metrics based on population
   678→ * Population status affects outcome probabilities
   679→ */
   680→export function updateOutcomeMetricsWithPopulation(state: GameState): void {
   681→  const pop = state.humanPopulationSystem;
   682→  const status = getPopulationStatus(pop.population);
   683→
   684→  // Utopia requires thriving population
   685→  if (status !== PopulationStatus.THRIVING && status !== PopulationStatus.STABLE) {
   686→    state.outcomeMetrics.utopiaProbability = 0;
   687→  }
   688→
   689→  // Dystopia possible at any population level
   690→  // (even small populations can be dystopian)
   691→
   692→  // Extinction probability increases as population falls
   693→  switch (status) {
   694→    case PopulationStatus.THRIVING:
   695→    case PopulationStatus.STABLE:
   696→      // No additional extinction risk
