// === CASCADE AMPLIFICATION (Non-Linear Feedback) ===
// When multiple systems fail simultaneously, effects compound
const breachedCount = boundaries.boundariesBreached;
if (breachedCount >= 8) {
  const cascadeAmplifier = 1.0 + Math.pow((breachedCount - 7) / 2, 2); // 1.0x → 2.25x at 9/9
  famineMortality *= cascadeAmplifier;
  diseaseMortality *= cascadeAmplifier;
  climateMortality *= cascadeAmplifier;
  ecosystemMortality *= cascadeAmplifier;
}

// === P0.6 (Oct 15, 2025): EPISODIC ENVIRONMENTAL SHOCKS ===
// Research: Environmental disasters are episodic, not continuous
// - 2003 European heatwave: 40,000 deaths (spike event)
// - Somalia famine 2010-12: 256,000 deaths over 2 years (prolonged event)
// - Agricultural shocks: 5-15% monthly decline during specific weather events
//
// Event probability increases with environmental stress
const eventProbability = Math.min(0.15, 0.02 + (breachedCount / 9) * 0.08); // 2-15% based on boundaries breached

// Check for new environmental shock this month
if (Math.random() < eventProbability) {
  // Event triggered! Determine type and magnitude
  const shockType = Math.random();
  const shockMagnitude = 1.5 + Math.random() * 1.5; // 150-300% spike

  if (shockType < 0.3) {
    // Heatwave / extreme weather (affects climate mortality)
    climateMortality *= shockMagnitude;
  } else if (shockType < 0.6) {
    // Drought / crop failure (affects famine)
    famineMortality *= shockMagnitude;
  } else if (shockType < 0.85) {
    // Disease outbreak / waterborne disease (affects disease mortality)
    diseaseMortality *= shockMagnitude;
  } else {
    // Ecosystem collapse event (affects ecosystem mortality)
    ecosystemMortality *= shockMagnitude;
  }
}

// Small baseline noise (±5%) between events
const baselineNoise = () => 0.95 + Math.random() * 0.1; // 95-105%
famineMortality *= baselineNoise();
diseaseMortality *= baselineNoise();
climateMortality *= baselineNoise();
ecosystemMortality *= baselineNoise();
pollutionMortality *= baselineNoise();

