  // DEPRECATED (backward compatibility, will be removed)
  basicNeeds?: {
    foodSecurity?: number;        
    waterSecurity?: number;       
    shelterSecurity?: number;     
  };
  regionalInequality?: {
    giniCoefficient: number;      
    topRegionQoL: number;         
    bottomRegionQoL: number;      
