    famine: famineMortality * scaleFactor,
    disease: diseaseMortality * scaleFactor,
    climate: climateMortality * scaleFactor,
    ecosystem: ecosystemMortality * scaleFactor,
    pollution: pollutionMortality * scaleFactor
  };
