// Action types for game events
export type GameAction = 
  | { type: 'ADVANCE_DAY' }
  | { type: 'ADVANCE_MONTH' }
  | { type: 'SET_SPEED'; payload: GameState['speed'] }
  | { type: 'UPDATE_CONFIG'; payload: Partial<ConfigurationSettings> }
  | { type: 'AI_ACTION'; payload: { agentId: string; action: string } }
