  numRuns = runsArg ? parseInt(runsArg) : 10;
  maxMonthsValue = maxMonthsArg ? parseInt(maxMonthsArg) : 240;
}

// Configuration
const NUM_RUNS = numRuns;
const MAX_MONTHS = maxMonthsValue;
const SEED_START = 42000;

