    // Economic & Social (ENHANCED)
    finalEconomicStage,
    finalUnemployment,
    finalTrust,
    finalSocialStability,
    finalWealthDistribution,
    economicTransitions,

    // Government metrics (ENHANCED)
    finalGovernmentLegitimacy,
    finalControlCapability,
    controlGap,
    governmentType,
    aiRightsRecognized,
    trainingDataQuality,

    // QoL breakdown (ENHANCED)
    qolBasicNeeds,
    qolPsychological,
    qolSocial,
    qolHealth,
    qolEnvironmental,

    // Sleeper tracking
    totalSleepers: sleepers.length,
    sleepersDetected,
    sleepersUndetected,
    sleepersAwakened,
    avgSleeperCapability,
    maxSleeperSpread,

    // Benchmark system
    totalBenchmarksRun: finalState.government.totalBenchmarksRun,
    finalEvalQuality: evalQuality,
    avgBenchmarkConfidence: avgConfidence,
    sandbaggingDetections,
    gamingDetections,

    // Extinction details
    extinctionType,
    extinctionPhase,
    extinctionMechanism,
    extinctionSeverity,

    // Critical events
    catastrophicActions,
    breachEvents,
    crisisEvents,
    technologyBreakthroughs,

    // Compute & Organizations metrics
    orgSurvivalRate,
    orgBankruptcies,
    finalOrgsAlive,
    totalOrgCapital,
    avgOrgCapital,
    maxOrgCapital,
    minOrgCapital,

    initialCompute,
    finalCompute,
    computeGrowthRate,
    dataCentersBuilt,
    totalDataCenters,
    governmentDataCenters,
    privateDataCenters,

    aiOwnershipConcentration,
    largestOrgModelCount,
    avgModelsPerOrg,
    orphanedAIs,

    totalMonthlyRevenue,
    avgMonthlyRevenue,
    revenueGrowthRate,
    revenueExpenseRatio,
    capitalAccumulation,

    totalConstructionProjects,
    completedConstructionProjects,
    totalTrainingProjects,
    completedTrainingProjects,
    avgConstructionTime,
    avgTrainingTime,

    capabilityLeader,
    capabilityLeaderValue,
    capabilityByOrg,
    modelCountByOrg,

    constructionDecisions,
    trainingDecisions,
    avgComputeUtilization,

    nationalComputeBuilt,
    dataCentersSeized,
    organizationsSubsidized,

    // Population & Mortality
    initialPopulation,
    finalPopulation,
    peakPopulation: pop.peakPopulation,
    populationDecline,
    totalDeaths,
    deathsNatural,
    deathsCrisis,
    deathsNuclear,
    deathsCascade,
    deathsMeaning,
    populationOutcome,
    geneticBottleneck,

    // Crisis Impact
    totalCrisisMonths,
    maxSimultaneousCrises,
    nuclearWarsCount,
    totalRefugees,
    refugeeCrisisCount,

    // Ecological Collapse
    finalClimateStability,
    finalBiodiversity,
    finalResourceReserves,
    tippingPointCascadeActive,
    tippingPointCascadeMonths,

    // Regional Inequality
    qolGiniCoefficient,
    qolTopRegion,
    qolBottomRegion,
    qolGap,
    crisisAffectedPopulation,

    // Per-Country Population (TIER 1.7.2)
    countriesDepopulated,
    nuclearPowersSurviving,
    aiHubsSurviving,
    depopulationEvents,

    // Organization Survival (TIER 1.7.3)
    organizationsBankrupt,
    organizationSurvivalRate,
    bankruptcyEvents
  });

  // Progress indicator
  if ((i + 1) % 10 === 0) {
    const elapsed = (Date.now() - startTime) / 1000;
    const perRun = elapsed / (i + 1);
    const remaining = perRun * (NUM_RUNS - i - 1);
    log(`  Completed ${i + 1}/${NUM_RUNS} runs (${elapsed.toFixed(1)}s elapsed, ~${remaining.toFixed(1)}s remaining)`);
  }
}

