    const orgName = event.split(' (')[0];
    if (orgName && orgName.trim().length > 0) { // Guard against empty string
      if (!orgBankruptcyFrequency[orgName]) {
        orgBankruptcyFrequency[orgName] = { count: 0, reasons: [] };
