content.content:
     1→#!/usr/bin/env tsx
     2→/**
     3→ * P0.4 (Oct 15, 2025): Diagnostic Monte Carlo Runner
     4→ *
     5→ * Runs Monte Carlo simulation with enhanced diagnostics to identify
     6→ * deterministic systems causing convergence
     7→ *
     8→ * Usage: npx tsx scripts/monteCarloDiagnostic.ts --runs 20 --months 240
     9→ */
    10→
    11→import { SimulationEngine } from '../src/simulation/engine';
    12→import { createDefaultInitialState } from '../src/simulation/initialization';
    13→import { analyzeDeterminism, formatDeterminismReport, DiagnosticLog } from '../src/simulation/diagnostics';
    14→import * as fs from 'fs';
    15→import * as path from 'path';
    16→
    17→// Parse command line arguments
    18→const args = process.argv.slice(2);
    19→const runsIndex = args.indexOf('--runs');
    20→const monthsIndex = args.indexOf('--months');
    21→
    22→const numRuns = runsIndex >= 0 ? parseInt(args[runsIndex + 1]) : 20;
    23→const numMonths = monthsIndex >= 0 ? parseInt(args[monthsIndex + 1]) : 240;
    24→
    25→console.log(`\n🔬 P0.4 DIAGNOSTIC MONTE CARLO`);
    26→console.log(`═══════════════════════════════════════════════════════`);
    27→console.log(`Runs: ${numRuns}`);
    28→console.log(`Duration: ${numMonths} months (${(numMonths/12).toFixed(1)} years)`);
    29→console.log(`Goal: Identify deterministic systems causing convergence\n`);
    30→
    31→// Storage for diagnostics from all runs
    32→const allDiagnostics: DiagnosticLog[] = [];
    33→const allResults: Array<{
    34→  seed: number;
    35→  outcome: string;
    36→  finalPopulation: number;
    37→  months: number;
    38→}> = [];
    39→
    40→// Run simulations
    41→for (let run = 1; run <= numRuns; run++) {
    42→  const seed = 42000 + run; // Fixed seed base for reproducibility
    43→
    44→  console.log(`\n[Run ${run}/${numRuns}] Seed: ${seed}`);
    45→
    46→  try {
    47→    const engine = new SimulationEngine({
    48→      seed,
    49→      maxMonths: numMonths,
    50→      logLevel: 'summary' // Minimal logging to reduce noise
    51→    });
    52→
    53→    const initialState = createDefaultInitialState();
    54→    const result = engine.run(initialState, {
    55→      maxMonths: numMonths,
    56→      checkActualOutcomes: true
    57→    });
    58→
    59→    // Store diagnostics
    60→    allDiagnostics.push(result.diagnostics);
    61→
    62→    // Store summary
    63→    const finalPop = result.finalState.humanPopulationSystem.population;
    64→    allResults.push({
    65→      seed,
    66→      outcome: result.summary.finalOutcome,
    67→      finalPopulation: finalPop,
    68→      months: result.summary.totalMonths
    69→    });
    70→
