     7→ * It's about multiple self-reinforcing positive feedback loops (spirals)
     8→ * 
     9→ * The 6 Upward Spirals:
    10→ * 1. Abundance - Material + Energy + Time liberation
    11→ * 2. Cognitive - Mental health + Purpose + Education
    12→ * 3. Democratic - Governance quality + Participation + Transparency
    13→ * 4. Scientific - Breakthrough acceleration + Discovery rate
    14→ * 5. Meaning - Purpose diversity + Self-actualization
    15→ * 6. Ecological - Ecosystem health + Climate + Biodiversity
    16→ * 
    17→ * Utopia condition: 3+ spirals sustained for 12+ months
    18→ * Virtuous cascade: 4+ spirals amplify each other (like our vicious cascades!)
    19→ */
    20→
    21→import type { GameState } from '../types/game';
    22→import { getTrustInAI } from './socialCohesion';
    23→
    24→export interface UpwardSpiral {
    25→  active: boolean;           // Is this spiral currently active?
    26→  strength: number;          // 0-1, how strong is it
    27→  monthsActive: number;      // How long has it been active consecutively
    28→  lastActivatedMonth: number; // When did it last turn on
    29→  lastDeactivatedMonth: number; // When did it last turn off
    30→}
    31→
    32→export interface UpwardSpiralState {
    33→  // The 6 spirals
    34→  abundance: UpwardSpiral;
    35→  cognitive: UpwardSpiral;
    36→  democratic: UpwardSpiral;
    37→  scientific: UpwardSpiral;
    38→  meaning: UpwardSpiral;
    39→  ecological: UpwardSpiral;
    40→  
    41→  // Cascade mechanics
    42→  cascadeActive: boolean;     // 4+ spirals → virtuous cascade
    43→  cascadeStrength: number;    // Cross-amplification factor (1.0-2.0+)
    44→  cascadeMonths: number;      // How long has cascade been active
    45→}
    46→
    47→export function initializeUpwardSpirals(): UpwardSpiralState {
    48→  const emptySpiral = (): UpwardSpiral => ({
    49→    active: false,
    50→    strength: 0,
    51→    monthsActive: 0,
    52→    lastActivatedMonth: -1,
    53→    lastDeactivatedMonth: -1
    54→  });
    55→  
    56→  return {
    57→    abundance: emptySpiral(),
    58→    cognitive: emptySpiral(),
    59→    democratic: emptySpiral(),
    60→    scientific: emptySpiral(),
    61→    meaning: emptySpiral(),
    62→    ecological: emptySpiral(),
    63→    cascadeActive: false,
    64→    cascadeStrength: 1.0,
    65→    cascadeMonths: 0
    66→  };
    67→}
    68→
    69→/**
    70→ * Update all upward spirals each month
    71→ * This is the main entry point called from the engine
    72→ */
    73→export function updateUpwardSpirals(state: GameState, currentMonth: number): void {
    74→  const spirals = state.upwardSpirals;
    75→  
    76→  // Check each spiral condition
    77→  updateAbundanceSpiral(spirals.abundance, state, currentMonth);
    78→  updateCognitiveSpiral(spirals.cognitive, state, currentMonth);
    79→  updateDemocraticSpiral(spirals.democratic, state, currentMonth);
    80→  updateScientificSpiral(spirals.scientific, state, currentMonth);
