   442→/**
   443→ * Check if Utopia conditions are met
   444→ * Utopia requires: 3+ spirals sustained for 12+ months + no active crises
   445→ */
   446→export function canDeclareUtopia(state: GameState): { can: boolean; reason: string; spiralCount: number } {
   447→  const spirals = state.upwardSpirals;
   448→  const qolSystems = state.qualityOfLifeSystems;
   449→  
   450→  // Count sustained spirals (active for 12+ months)
   451→  const sustainedSpirals = [
   452→    spirals.abundance,
   453→    spirals.cognitive,
   454→    spirals.democratic,
   455→    spirals.scientific,
   456→    spirals.meaning,
   457→    spirals.ecological
   458→  ].filter(s => s.active && s.monthsActive >= 12);
   459→  
   460→  const sustainedCount = sustainedSpirals.length;
   461→  
   462→  // Need 3+ sustained spirals
   463→  if (sustainedCount < 3) {
   464→    return {
   465→      can: false,
   466→      reason: `Only ${sustainedCount} sustained spirals (need 3+). Active spirals: ${getActiveSpiralNames(spirals).join(', ')}`,
   467→      spiralCount: sustainedCount
   468→    };
   469→  }
   470→  
   471→  // NEW (Oct 12, 2025): Check survival fundamentals
   472→  // Utopia requires ALL survival needs met globally
   473→  // Research: Can't have utopia if people are starving/dying regardless of other metrics
   474→  const survival = qolSystems.survivalFundamentals;
   475→  if (survival) {
   476→    if (survival.foodSecurity < 0.7) {
   477→      return {
   478→        can: false,
   479→        reason: `Food insecurity (${(survival.foodSecurity * 100).toFixed(0)}% < 70% threshold)`,
   480→        spiralCount: sustainedCount
   481→      };
   482→    }
   483→    if (survival.waterSecurity < 0.7) {
   484→      return {
   485→        can: false,
   486→        reason: `Water insecurity (${(survival.waterSecurity * 100).toFixed(0)}% < 70% threshold)`,
   487→        spiralCount: sustainedCount
   488→      };
   489→    }
   490→    if (survival.thermalHabitability < 0.7) {
   491→      return {
   492→        can: false,
   493→        reason: `Thermal uninhabitability (${(survival.thermalHabitability * 100).toFixed(0)}% habitable < 70% threshold)`,
   494→        spiralCount: sustainedCount
   495→      };
   496→    }
   497→    if (survival.shelterSecurity < 0.7) {
   498→      return {
   499→        can: false,
   500→        reason: `Shelter insecurity (${(survival.shelterSecurity * 100).toFixed(0)}% < 70% threshold)`,
   501→        spiralCount: sustainedCount
   502→      };
   503→    }
   504→  }
   505→  
   506→  // NEW (Oct 12, 2025): Check distribution metrics
   507→  // Utopia requires reasonable equality - can't have "Elysium" scenario
   508→  // Research: Gini >0.40 = problematic inequality (Wilkinson & Pickett)
   509→  const distribution = qolSystems.distribution;
   510→  if (distribution) {
   511→    if (distribution.globalGini > 0.40) {
   512→      return {
   513→        can: false,
   514→        reason: `High inequality (Gini ${(distribution.globalGini).toFixed(2)} > 0.40 threshold)`,
   515→        spiralCount: sustainedCount
   516→      };
   517→    }
   518→    if (distribution.worstRegionQoL < 0.50) {
   519→      return {
   520→        can: false,
   521→        reason: `Worst region suffering (QoL ${(distribution.worstRegionQoL).toFixed(2)} < 0.50 Rawlsian minimum)`,
   522→        spiralCount: sustainedCount
   523→      };
   524→    }
   525→    if (distribution.isDystopicInequality) {
   526→      return {
   527→        can: false,
   528→        reason: `Dystopic inequality detected (some regions thriving while others suffer)`,
   529→        spiralCount: sustainedCount
   530→      };
   531→    }
   532→    if (distribution.isRegionalDystopia) {
   533→      return {
   534→        can: false,
   535→        reason: `Regional dystopia (>30% in crisis while others prosper)`,
   536→        spiralCount: sustainedCount
   537→      };
   538→    }
   539→  }
   540→  
   541→  // Check for active crises (can't have utopia with crises)
   542→  const env = state.environmentalAccumulation;
   543→  const social = state.socialAccumulation;
   544→  const tech = state.technologicalRisk;
   545→  
   546→  const activeCrises = [
   547→    env.resourceCrisisActive && 'Resource',
   548→    env.pollutionCrisisActive && 'Pollution',
   549→    env.climateCrisisActive && 'Climate',
   550→    env.ecosystemCrisisActive && 'Ecosystem',
   551→    social.meaningCollapseActive && 'Meaning',
   552→    social.socialUnrestActive && 'Social Unrest',
   553→    social.institutionalFailureActive && 'Institutional',
   554→    tech.controlLossActive && 'Control Loss',
   555→    tech.corporateDystopiaActive && 'Corporate Dystopia',
   556→    tech.complacencyCrisisActive && 'Complacency'
   557→  ].filter(Boolean) as string[];
   558→  
   559→  if (activeCrises.length > 0) {
   560→    return {
   561→      can: false,
   562→      reason: `Active crises present: ${activeCrises.join(', ')}`,
   563→      spiralCount: sustainedCount
   564→    };
   565→  }
   566→  
   567→  // Success! All conditions met
   568→  return {
   569→    can: true,
   570→    reason: `${sustainedCount} upward spirals sustained for 12+ months: ${getSustainedSpiralNames(spirals).join(', ')}`,
   571→    spiralCount: sustainedCount
   572→  };
   573→}
