export function calculateEmploymentEffects(
  aiCapability: number,
  taskComplexity: number,
  timeInPhase: number
): {
  productivityMultiplier: number;
  employmentMultiplier: number;
  displacementRisk: number;
} {
  const ratio = aiCapability / taskComplexity;

